    ('35cd4862-9db6-522c-a386-68737f46de45'::uuid, 'Quiz — Duras, 1950 — la concession incultivable', 'Français', '1re', 'Un Barrage contre le Pacifique, Marguerite Duras', '6a2278a8-36b6-581d-9725-ac14ffbb2c16'::uuid),
    ('4bc7b166-5257-548a-bb31-fbb9a34eb49f'::uuid, 'Quiz — Rimbaud, 1873 — le seul livre qu’il ait publié lui-même', 'Français', '1re', 'Une Saison en Enfer, Arthur Rimbaud', 'c679ce59-7485-575d-ba9c-fd9c3eb9217c'::uuid),
    ('b4ec9000-7740-52e0-b7c4-b7b6f698ac8f'::uuid, 'Quiz — Maupassant, 1883 — « l’humble vérité »', 'Français', '1re', 'Une Vie, Guy de Maupassant', '383424ed-30e4-55cb-8076-aac04d729617'::uuid),
    ('c01a1bbe-0358-5d70-ad08-20927df576b5'::uuid, 'Quiz — Tournier, 1967 — Robinson retourné', 'Français', '1re', 'Vendredi ou les Limbes du Pacifique, Michel Tournier', '17fd2394-2407-5e19-a590-e074dbbaf173'::uuid),
    ('ad5d89f4-e2dd-54f7-ab31-6a7abb97bdc1'::uuid, 'Quiz — Saint-Exupéry, 1931 — le prix du courrier', 'Français', '1re', 'Vol de nuit, Antoine de Saint-Exupéry', '5b6d822f-45af-5357-99be-ca45edf330cf'::uuid),
    ('ae6261e6-b153-5922-8c5d-fe9a840e2ef7'::uuid, 'Quiz — Céline, 1932 — la langue parlée entre en littérature', 'Français', '1re', 'Voyage au bout de la nuit, Louis-Ferdinand Céline', '927d3962-9ac3-50ce-9119-41eb7fc40bd2'::uuid),
    ('620a46e3-8eaa-51e9-899b-47b0697d213c'::uuid, 'Quiz — Verne, 1864 — descendre par un volcan', 'Français', '1re', 'Voyage au centre de la Terre, Jules Verne', '394ef05a-17bf-5bb2-b516-22e9b782b3a7'::uuid),
    ('b3203244-1062-5cc3-9f56-41f8d167382d'::uuid, 'Quiz — Voltaire, 1747 — la providence en question', 'Français', '1re', 'Zadig ou la Destinée, Voltaire', '385a4a65-b2b3-56bb-9746-cbe89ccc55d9'::uuid),
    ('02cdad23-ef9e-5d36-bbca-80d560ce259e'::uuid, 'Quiz — Queneau, 1959 — « Doukipudonktan »', 'Français', '1re', 'Zazie dans le métro, Raymond Queneau', '2eec2061-88f5-5b42-be5e-a2e99d04a5d4'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('8a8a1e04-d8aa-51b3-8a47-41ab4ba7fd05'::uuid, '61c86bd6-8b94-531c-8074-821a2636d880'::uuid, 'Pourquoi le titre parle-t-il d’« outre-tombe » ?', 'mcq', '["L’œuvre devait paraître après la mort de l’auteur","Elle raconte des visions surnaturelles","Elle est écrite dans un cimetière","Elle s’adresse aux morts"]'::jsonb, 0, 'Publiée en 1849-1850, elle s’adresse au lecteur depuis la tombe.', 1),
    ('4c899e81-837a-5ec1-891e-a87d9ecad5af'::uuid, '61c86bd6-8b94-531c-8074-821a2636d880'::uuid, 'Où se déroule l’enfance racontée dans les premiers livres ?', 'mcq', '["Au château de Combourg, en Bretagne","À Paris","En Normandie","En Amérique"]'::jsonb, 0, 'Avec un père taciturne et la sœur Lucile.', 2),
    ('9d18617e-0240-50fa-af3b-74157be52df6'::uuid, '61c86bd6-8b94-531c-8074-821a2636d880'::uuid, 'Quel voyage marque sa jeunesse ?', 'mcq', '["Un voyage en Amérique, en 1791","Un voyage en Russie","Un tour d’Italie","Un séjour en Égypte"]'::jsonb, 0, 'Il en tirera Atala et René.', 3),
    ('5c30522a-d733-50f7-8a12-a11b783cb0b0'::uuid, '61c86bd6-8b94-531c-8074-821a2636d880'::uuid, 'Quelle figure occupe des livres entiers de l’œuvre ?', 'mcq', '["Napoléon","Louis XVI","Robespierre","Talleyrand"]'::jsonb, 0, 'Un double fascinant et détesté.', 4),
    ('ec99ac9b-f0f4-5860-a211-b83e7a834330'::uuid, '61c86bd6-8b94-531c-8074-821a2636d880'::uuid, 'Quelle est la particularité de l’écriture du temps chez Chateaubriand ?', 'mcq', '["Il superpose les époques et se compare à lui-même","Il suit un ordre strictement chronologique","Il refuse toute date","Il écrit au présent uniquement"]'::jsonb, 0, '« Je me trouve entre deux siècles comme au confluent de deux fleuves. »', 5),
    ('f48bd50e-0e72-5c8b-87fe-c5d551d4be60'::uuid, '61c86bd6-8b94-531c-8074-821a2636d880'::uuid, 'L’œuvre a été publiée du vivant de l’auteur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle paraît en 1849-1850, après sa mort.', 6),
    ('13d7b2c9-a0db-524f-8d9a-aef04a1ed129'::uuid, '2857273a-393c-59d8-bced-2ad22e3be42d'::uuid, 'Quelle période ce tome couvre-t-il ?', 'mcq', '["Août 1944 – janvier 1946","1940-1942","1958-1962","1939-1940"]'::jsonb, 0, 'De la libération de Paris à sa démission.', 1),
    ('a65841d7-983a-5fb4-96d0-1376f063ad7b'::uuid, '2857273a-393c-59d8-bced-2ad22e3be42d'::uuid, 'Quel événement clôt le volume ?', 'mcq', '["La démission de de Gaulle en janvier 1946","La victoire de mai 1945","Le retour au pouvoir en 1958","Le vote de la Constitution"]'::jsonb, 0, 'Il quitte le pouvoir face au régime des partis.', 2),
    ('b4204d15-c2d2-52e2-b7cf-e452d7efe23e'::uuid, '2857273a-393c-59d8-bced-2ad22e3be42d'::uuid, 'Quelle particularité stylistique frappe le lecteur ?', 'mcq', '["De Gaulle parle de lui à la troisième personne","Il écrit en vers","Il refuse toute date","Il emploie un style familier"]'::jsonb, 0, 'L’homme devient personnage, le récit devient épopée.', 3),
    ('42334d4f-3108-5528-8d3f-5d2fe6bd5316'::uuid, '2857273a-393c-59d8-bced-2ad22e3be42d'::uuid, 'Quelle est la phrase la plus célèbre des Mémoires ?', 'mcq', '["« Toute ma vie, je me suis fait une certaine idée de la France »","« La France a perdu une bataille »","« Je vous ai compris »","« Vive le Québec libre »"]'::jsonb, 0, 'Elle ouvre le premier tome, L’Appel.', 4),
    ('9f55b4e4-e3f2-55fd-96ac-b91706c91719'::uuid, '2857273a-393c-59d8-bced-2ad22e3be42d'::uuid, 'Quelles réformes de cette période sont évoquées ?', 'mcq', '["Vote des femmes, nationalisations, Sécurité sociale","La décentralisation","La réforme du franc","L’indépendance de l’Algérie"]'::jsonb, 0, 'Le programme du Conseil national de la Résistance est mis en œuvre.', 5),
    ('7c5ee468-ec86-551a-85d9-f156c9ab695c'::uuid, '2857273a-393c-59d8-bced-2ad22e3be42d'::uuid, 'Ces Mémoires sont un simple document sans ambition littéraire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’ambition littéraire y est revendiquée, et le style très travaillé.', 6),
    ('7aab241f-0fcb-517e-be33-b064e5d6e8e2'::uuid, '67d83ea7-fd3b-5503-808b-341295dbe680'::uuid, 'De quelle nationalité est Hélène Dorion ?', 'mcq', '["Québécoise","Française","Belge","Suisse"]'::jsonb, 0, 'Elle est la première autrice vivante au programme du bac de français.', 1),
    ('84bbbf5d-236d-58ce-bd05-817f57a562d3'::uuid, '67d83ea7-fd3b-5503-808b-341295dbe680'::uuid, 'Combien de sections compose le recueil ?', 'mcq', '["Quatre","Deux","Six","Douze"]'::jsonb, 0, 'Précédées d’un poème liminaire et ouvertes par des exergues.', 2),
    ('f8bba86d-f27e-5515-ae44-8dc7c8157708'::uuid, '67d83ea7-fd3b-5503-808b-341295dbe680'::uuid, 'Que signifie le possessif du titre ?', 'mcq', '["La forêt est un paysage intérieur autant qu’extérieur","La poétesse possède une forêt","Ce sont des forêts imaginaires","Le titre est ironique"]'::jsonb, 0, 'L’arbre sert à dire une vie humaine.', 3),
    ('dac59e14-2d01-5b39-aa71-39fd02712473'::uuid, '67d83ea7-fd3b-5503-808b-341295dbe680'::uuid, 'Quelle forme prennent les poèmes ?', 'mcq', '["Vers libres, presque sans ponctuation, avec beaucoup de blancs","Sonnets","Alexandrins rimés","Poèmes en prose"]'::jsonb, 0, 'Le silence fait partie du texte.', 4),
    ('43260570-ac23-5405-88dc-0c73fb9f3b49'::uuid, '67d83ea7-fd3b-5503-808b-341295dbe680'::uuid, 'Comment la dimension écologique s’exprime-t-elle ?', 'mcq', '["Comme une appartenance vécue au vivant, non comme un discours","Par un manifeste militant","Par des données scientifiques","Elle est absente"]'::jsonb, 0, 'Quand la forêt brûle, c’est nous que la perte atteint.', 5),
    ('d5b1053f-ce14-5b2f-9969-f8013803e021'::uuid, '67d83ea7-fd3b-5503-808b-341295dbe680'::uuid, 'Quel deuil traverse le recueil ?', 'mcq', '["Celui du père","Celui d’un enfant","Celui d’un ami","Aucun"]'::jsonb, 0, 'Il nourrit notamment la deuxième section.', 6),
    ('473fc026-6906-5c73-8bc2-0e3ebb8ae94f'::uuid, '67d09b07-1bd4-5b50-8bbd-7f57bae2aa32'::uuid, 'Quel est le sujet annoncé du poème ?', 'mcq', '["Les formes changées en corps nouveaux","La fondation de Rome","La guerre de Troie","Les travaux des champs"]'::jsonb, 0, 'La transformation est la loi du monde selon Ovide.', 1),
    ('a48883e0-e701-5d69-910a-f581b12b0037'::uuid, '67d09b07-1bd4-5b50-8bbd-7f57bae2aa32'::uuid, 'Combien de récits le poème contient-il environ ?', 'mcq', '["Deux cent cinquante","Vingt","Mille","Cinquante"]'::jsonb, 0, 'Répartis en quinze livres et douze mille vers.', 2),
    ('1c7e87fd-eac5-56d2-92be-f7856da91a7a'::uuid, '67d09b07-1bd4-5b50-8bbd-7f57bae2aa32'::uuid, 'En quoi Daphné est-elle transformée ?', 'mcq', '["En laurier","En fleur","En source","En araignée"]'::jsonb, 0, 'Pour échapper à la poursuite d’Apollon.', 3),
    ('cbab2220-ec28-5d6b-a778-08de0cf1e81d'::uuid, '67d09b07-1bd4-5b50-8bbd-7f57bae2aa32'::uuid, 'Qui tombe amoureux de son propre reflet ?', 'mcq', '["Narcisse","Pygmalion","Orphée","Icare"]'::jsonb, 0, 'Il est changé en fleur ; Écho, elle, est réduite à une voix.', 4),
    ('09240414-ee15-5f45-9998-1a004ce13b4e'::uuid, '67d09b07-1bd4-5b50-8bbd-7f57bae2aa32'::uuid, 'Quel événement suit de peu l’achèvement du poème ?', 'mcq', '["L’exil d’Ovide à Tomes, décidé par Auguste","La mort de César","L’incendie de Rome","La conquête de la Gaule"]'::jsonb, 0, 'Les raisons de cet exil restent débattues.', 5),
    ('84557c85-f524-58e1-97be-fa77b11599e8'::uuid, '67d09b07-1bd4-5b50-8bbd-7f57bae2aa32'::uuid, 'Le poème n’a eu qu’une influence limitée sur la littérature européenne.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est le grand réservoir de mythes de toute la culture occidentale.', 6),
    ('a0095adc-7781-5a33-8239-a93d748b3f8b'::uuid, '30ab2b1b-f4b3-5f53-bebd-911d889ab5c8'::uuid, 'D’où vient Micromégas ?', 'mcq', '["D’une planète de l’étoile Sirius","De Saturne","De la Lune","De Mars"]'::jsonb, 0, 'Il mesure huit lieues et vit des centaines de siècles.', 1),
    ('ff5b9e54-c3a6-5855-9f96-03963e7514e1'::uuid, '30ab2b1b-f4b3-5f53-bebd-911d889ab5c8'::uuid, 'Pourquoi a-t-il été banni de sa planète ?', 'mcq', '["Pour un livre jugé hérétique","Pour un crime","Pour désobéissance militaire","Il est parti volontairement"]'::jsonb, 0, 'La satire de l’intolérance commence dès la première page.', 2),
    ('5a9ac64a-ed5b-55da-8cf3-40965293ff9f'::uuid, '30ab2b1b-f4b3-5f53-bebd-911d889ab5c8'::uuid, 'Comment les géants découvrent-ils les humains ?', 'mcq', '["À la loupe, sur un navire revenant du cercle polaire","Par un télescope","Par des signaux lumineux","Ils ne les découvrent pas"]'::jsonb, 0, 'Ils croyaient d’abord la Terre déserte.', 3),
    ('6ffe4308-0c5e-57f6-935d-58d49f3931ac'::uuid, '30ab2b1b-f4b3-5f53-bebd-911d889ab5c8'::uuid, 'Qu’est-ce qui étonne Micromégas chez les humains ?', 'mcq', '["Ils savent mesurer les astres, mais se disputent sur l’âme","Ils sont pacifiques","Ils vivent très longtemps","Ils ignorent tout de la science"]'::jsonb, 0, 'Le savoir et la bêtise y cohabitent.', 4),
    ('af0dd9a5-26ad-5106-84af-52559b93414a'::uuid, '30ab2b1b-f4b3-5f53-bebd-911d889ab5c8'::uuid, 'Que contient le livre offert par Micromégas ?', 'mcq', '["Rien : il est entièrement blanc","La formule de l’immortalité","Un traité d’astronomie","Une carte du système solaire"]'::jsonb, 0, 'La chute est un chef-d’œuvre d’ironie.', 5),
    ('2a490596-ebf0-5496-92f9-4ea3ac8af48e'::uuid, '30ab2b1b-f4b3-5f53-bebd-911d889ab5c8'::uuid, 'Le conte repose sur le changement d’échelle.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le procédé rend visibles l’orgueil et la petitesse humaines.', 6),
    ('417aef91-7cb8-56b2-870a-e96452aaad9f'::uuid, '8053730b-32c5-5008-9c44-2b6587193ea7'::uuid, 'Par quelle question le livre s’ouvre-t-il ?', 'mcq', '["« Qui suis-je ? »","« Où vais-je ? »","« Qu’est-ce que le surréalisme ? »","« Que puis-je savoir ? »"]'::jsonb, 0, 'Le livre est une enquête sur l’identité du narrateur.', 1),
    ('0360cea4-6bf3-55b6-87b7-9ee89bbce894'::uuid, '8053730b-32c5-5008-9c44-2b6587193ea7'::uuid, 'Que remplacent les photographies dans le livre ?', 'mcq', '["Les descriptions","Les dialogues","Les chapitres","Les notes de bas de page"]'::jsonb, 0, 'Breton refuse la description romanesque.', 2),
    ('b872a3f2-4817-5657-b122-6626282251ea'::uuid, '8053730b-32c5-5008-9c44-2b6587193ea7'::uuid, 'Que signifie le prénom Nadja ?', 'mcq', '["Le commencement du mot « espérance » en russe","Étoile","Nuit","Liberté"]'::jsonb, 0, 'C’est elle qui donne cette explication.', 3),
    ('45ad3a36-cdf9-59b5-84c1-bf9d5a4d95d1'::uuid, '8053730b-32c5-5008-9c44-2b6587193ea7'::uuid, 'Que devient Nadja à la fin ?', 'mcq', '["Elle est internée et disparaît du récit","Elle épouse Breton","Elle quitte Paris","Elle devient peintre"]'::jsonb, 0, 'L’attitude de Breton à ce moment est souvent discutée.', 4),
    ('b4cef323-8de9-56aa-9e53-530a8d61c83e'::uuid, '8053730b-32c5-5008-9c44-2b6587193ea7'::uuid, 'Quelle formule clôt le livre ?', 'mcq', '["« La beauté sera convulsive ou ne sera pas »","« L’imagination reprend ses droits »","« Changer la vie »","« Je est un autre »"]'::jsonb, 0, 'Elle est devenue un slogan du surréalisme.', 5),
    ('ba219a5f-dc2f-5a65-b2b2-6f9faa92f6bd'::uuid, '8053730b-32c5-5008-9c44-2b6587193ea7'::uuid, 'Nadja est un roman classique avec intrigue construite.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le livre refuse le roman : ni intrigue construite, ni descriptions, ni invention revendiquée.', 6),
    ('72790294-7727-52af-85c4-5251e3737018'::uuid, 'e8b29a4d-5d80-57cb-9379-0e713bbacbb8'::uuid, 'Qui est Nana ?', 'mcq', '["La fille de Gervaise et Coupeau, devenue actrice puis courtisane","Une aristocrate déclassée","Une ouvrière du textile","Une chanteuse de rue"]'::jsonb, 0, 'Elle débute dans La Blonde Vénus, aux Variétés.', 1),
    ('824d8606-4ff6-5d42-b071-ef3909d3ed7f'::uuid, 'e8b29a4d-5d80-57cb-9379-0e713bbacbb8'::uuid, 'Pourquoi triomphe-t-elle au théâtre ?', 'mcq', '["Elle paraît presque nue, bien qu’elle chante faux","Elle a un immense talent d’actrice","Elle est protégée par l’Empereur","Elle a écrit la pièce"]'::jsonb, 0, 'Le succès repose sur le désir, non sur l’art.', 2),
    ('434eb3e4-ab3c-5847-8f82-aab16100c59e'::uuid, 'e8b29a4d-5d80-57cb-9379-0e713bbacbb8'::uuid, 'Quel personnage se traîne aux pieds de Nana ?', 'mcq', '["Le comte Muffat, chambellan de l’Empereur","Le banquier Steiner seul","Vandeuvres","Fauchery"]'::jsonb, 0, 'Sa déchéance est le fil rouge du roman.', 3),
    ('3989857d-af90-5a3e-bdb1-b917691fdaed'::uuid, 'e8b29a4d-5d80-57cb-9379-0e713bbacbb8'::uuid, 'Quelle scène constitue le sommet du roman ?', 'mcq', '["La journée du Grand Prix de Paris","La première au théâtre","Le souper chez Nana","L’enterrement final"]'::jsonb, 0, 'Une pouliche nommée Nana y gagne la course.', 4),
    ('23e7adde-cda7-5738-82a2-272e997777c6'::uuid, 'e8b29a4d-5d80-57cb-9379-0e713bbacbb8'::uuid, 'Comment Nana meurt-elle ?', 'mcq', '["Défigurée par la petite vérole, seule dans un hôtel","Assassinée","Ruinée en prison","De vieillesse"]'::jsonb, 0, 'Sous les fenêtres, la foule crie « À Berlin ! ».', 5),
    ('69283c35-a0b6-5ac5-8e52-3fa2449c775a'::uuid, 'e8b29a4d-5d80-57cb-9379-0e713bbacbb8'::uuid, 'Le roman fait de Nana une allégorie de la société du Second Empire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La « mouche d’or » née du ruisseau pourrit tout ce qu’elle touche.', 6),
    ('bcc671a9-29db-5406-b86c-b6835f24be43'::uuid, '4acaf942-b283-5ca0-a8a2-944e6081403e'::uuid, 'En quelle année se déroule l’action ?', 'mcq', '["1482","1789","1348","1572"]'::jsonb, 0, 'Paris à la fin du Moyen Âge.', 1),
    ('76c33a40-c2bb-581e-ac00-a70ce577a903'::uuid, '4acaf942-b283-5ca0-a8a2-944e6081403e'::uuid, 'Qui est Claude Frollo ?', 'mcq', '["L’archidiacre qui a recueilli Quasimodo et désire Esmeralda","Le capitaine des archers","Le roi des truands","Le père d’Esmeralda"]'::jsonb, 0, 'Son désir refoulé déclenche toute la tragédie.', 2),
    ('3bf1b781-ea84-5a6d-8598-a31b7a8756ba'::uuid, '4acaf942-b283-5ca0-a8a2-944e6081403e'::uuid, 'Où Quasimodo met-il Esmeralda à l’abri ?', 'mcq', '["Dans la cathédrale, lieu d’asile inviolable","Dans la Cour des miracles","Au Louvre","Chez Gringoire"]'::jsonb, 0, 'La Cour des miracles viendra l’en « délivrer », provoquant un massacre.', 3),
    ('791fc48a-c394-5afe-b5bc-f5ee772851c5'::uuid, '4acaf942-b283-5ca0-a8a2-944e6081403e'::uuid, 'Que signifie « Ceci tuera cela » ?', 'mcq', '["Le livre imprimé remplace la cathédrale comme livre du peuple","La foule tuera le roi","Le fer tuera la pierre","La science tuera la foi"]'::jsonb, 0, 'C’est le chapitre théorique du roman.', 4),
    ('829ea273-d985-596f-bdb6-c8ceb53eba65'::uuid, '4acaf942-b283-5ca0-a8a2-944e6081403e'::uuid, 'Quel effet le roman a-t-il eu sur le monument ?', 'mcq', '["Son succès a conduit à la restauration de Notre-Dame","Il a accéléré sa démolition","Il n’a eu aucun effet","Il a fait fermer la cathédrale"]'::jsonb, 0, 'Hugo militait pour la sauvegarde du patrimoine médiéval.', 5),
    ('dcbe7ea9-7aa8-5b8e-a1bb-feb0c25c59e2'::uuid, '4acaf942-b283-5ca0-a8a2-944e6081403e'::uuid, 'Le roman se termine par le mariage d’Esmeralda et Phœbus.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Esmeralda est pendue ; Quasimodo va mourir près de son corps.', 6),
    ('c924d7d0-cd32-5c08-8a69-5a22d0648a1d'::uuid, 'd210946d-b171-5d9f-842a-c50c05fdf740'::uuid, 'Combien de temps Ulysse met-il à rentrer après la guerre ?', 'mcq', '["Dix ans","Deux ans","Vingt ans","Un an"]'::jsonb, 0, 'La guerre elle-même avait duré dix ans.', 1),
    ('2f2d585a-d5bd-5b69-bd65-ba7a357a644b'::uuid, 'd210946d-b171-5d9f-842a-c50c05fdf740'::uuid, 'Qui assiège Pénélope à Ithaque ?', 'mcq', '["Les prétendants qui pillent le palais","Les Troyens","Les Phéaciens","Les hommes de Circé"]'::jsonb, 0, 'Elle les tient en échec par la ruse de la toile.', 2),
    ('69444515-4118-56fc-b310-174bb8201b97'::uuid, 'd210946d-b171-5d9f-842a-c50c05fdf740'::uuid, 'Où Ulysse raconte-t-il ses aventures ?', 'mcq', '["Chez les Phéaciens","À Ithaque","Chez Circé","Aux Enfers"]'::jsonb, 0, 'Le récit est enchâssé : Ulysse est narrateur second.', 3),
    ('56436d52-7fe3-5a0e-bf33-7839d6e29c21'::uuid, 'd210946d-b171-5d9f-842a-c50c05fdf740'::uuid, 'Quelle épreuve permet à Ulysse de se faire reconnaître ?', 'mcq', '["L’épreuve de l’arc","Une course de chars","Un combat naval","Une énigme"]'::jsonb, 0, 'Seul lui peut bander l’arc et traverser les douze haches.', 4),
    ('ade8aefa-e001-52ec-868e-769d20e3932e'::uuid, 'd210946d-b171-5d9f-842a-c50c05fdf740'::uuid, 'Comment Pénélope éprouve-t-elle Ulysse ?', 'mcq', '["Par le secret du lit taillé dans un olivier","Par une question sur Troie","Par une cicatrice","Par un anneau"]'::jsonb, 0, 'La cicatrice, elle, sert à la nourrice Euryclée.', 5),
    ('cc6ba646-0ef2-5187-b2c1-91e6b0747a98'::uuid, 'd210946d-b171-5d9f-842a-c50c05fdf740'::uuid, 'Le récit suit un ordre strictement chronologique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il alterne trois fils et pratique le récit enchâssé : une construction très moderne.', 6),
    ('e39f61b3-5228-5a7b-817e-bab8c69917dd'::uuid, '2acd8d3e-600a-50ea-ba33-1e561468e55d'::uuid, 'Pourquoi Œdipe mène-t-il l’enquête ?', 'mcq', '["L’oracle exige que l’on chasse le meurtrier de Laïos pour arrêter la peste","Il veut prouver son innocence","Créon l’y oblige","Jocaste le lui demande"]'::jsonb, 0, 'Il ignore qu’il enquête sur lui-même.', 1),
    ('2cb87182-0745-5ada-8ba4-00cb79662dba'::uuid, '2acd8d3e-600a-50ea-ba33-1e561468e55d'::uuid, 'Qui accuse Œdipe le premier ?', 'mcq', '["Le devin Tirésias","Créon","Jocaste","Le berger"]'::jsonb, 0, 'Œdipe crie alors au complot.', 2),
    ('3cf5115f-1579-5a18-9728-fad9cd6be01d'::uuid, '2acd8d3e-600a-50ea-ba33-1e561468e55d'::uuid, 'Qu’a fait Œdipe sans le savoir ?', 'mcq', '["Il a tué son père et épousé sa mère","Il a trahi Thèbes","Il a offensé les dieux","Il a volé le trône"]'::jsonb, 0, 'L’oracle s’accomplit malgré tout ce qui fut tenté pour l’éviter.', 3),
    ('823df6c1-d171-5df4-8f23-9b36df52b626'::uuid, '2acd8d3e-600a-50ea-ba33-1e561468e55d'::uuid, 'Comment se termine la pièce ?', 'mcq', '["Jocaste se pend, Œdipe se crève les yeux et part en exil","Œdipe est acquitté","La peste cesse sans autre conséquence","Créon est condamné"]'::jsonb, 0, 'Il se punit lui-même de n’avoir pas vu.', 4),
    ('7d178040-b37b-5b05-9cca-226cc290f7f4'::uuid, '2acd8d3e-600a-50ea-ba33-1e561468e55d'::uuid, 'Quels termes d’Aristote la pièce illustre-t-elle ?', 'mcq', '["Péripétie et reconnaissance","Unité de ton et bienséance","Catharsis et chœur seulement","Prologue et épilogue"]'::jsonb, 0, 'Le renversement et la reconnaissance y coïncident.', 5),
    ('da8bd59e-52aa-5b75-b73f-3dce58b1f9ca'::uuid, '2acd8d3e-600a-50ea-ba33-1e561468e55d'::uuid, 'La pièce est construite comme une enquête.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le juge y découvre qu’il est le coupable : c’est un modèle du genre.', 6),
    ('41b909aa-4119-5246-8993-806f84dae97a'::uuid, '102c556a-d8b3-5d73-91f3-1db1b214d620'::uuid, 'Quel genre Musset revendique-t-il pour cette pièce ?', 'mcq', '["Le proverbe","La tragédie","La farce","Le vaudeville"]'::jsonb, 0, 'Publiée dans Un spectacle dans un fauteuil, elle était destinée à la lecture.', 1),
    ('a93c09fa-1fde-5f4b-8295-bfa61c396a5d'::uuid, '102c556a-d8b3-5d73-91f3-1db1b214d620'::uuid, 'Pourquoi Camille refuse-t-elle Perdican ?', 'mcq', '["Les religieuses lui ont fait craindre l’infidélité des hommes","Elle en aime un autre","Son père s’y oppose","Elle veut voyager"]'::jsonb, 0, 'Son refus vient d’une peur apprise.', 2),
    ('66882be7-c748-5708-ad92-6116d80acee3'::uuid, '102c556a-d8b3-5d73-91f3-1db1b214d620'::uuid, 'Qui est Rosette ?', 'mcq', '["Une paysanne, sœur de lait de Camille","La sœur de Perdican","Une religieuse","La fille du baron"]'::jsonb, 0, 'Elle est la seule à ne pas jouer — et la seule qui meurt.', 3),
    ('167d7142-ba72-5e29-ae0d-eedf0ee3f982'::uuid, '102c556a-d8b3-5d73-91f3-1db1b214d620'::uuid, 'Quel piège Camille tend-elle ?', 'mcq', '["Elle cache Rosette pour lui faire entendre les aveux de Perdican","Elle écrit une fausse lettre","Elle fait venir un prêtre","Elle feint de partir"]'::jsonb, 0, 'Le stratagème se retourne contre elle.', 4),
    ('9af8daaa-3726-5f3f-966b-5c4c1270af45'::uuid, '102c556a-d8b3-5d73-91f3-1db1b214d620'::uuid, 'Par quels mots la pièce se termine-t-elle ?', 'mcq', '["« Elle est morte. Adieu, Perdican ! »","« Adieu, Camille »","« Nous serons heureux »","« Il est trop tard »"]'::jsonb, 0, 'L’amour est reconnu au moment où il devient impossible.', 5),
    ('92f93690-733e-5256-9411-ebe45cd3789a'::uuid, '102c556a-d8b3-5d73-91f3-1db1b214d620'::uuid, 'La pièce mêle comique, lyrique et tragique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la marque du drame romantique.', 6),
    ('78cf3437-a615-5f33-a547-62befe8c50a3'::uuid, '9c71054b-dad3-5672-870d-0ec07504a17d'::uuid, 'Quel marché Follavoine espère-t-il obtenir ?', 'mcq', '["Des pots de chambre incassables pour l’armée","Des porcelaines de luxe","Un contrat de vaisselle d’État","Une commande municipale"]'::jsonb, 0, 'Le sujet trivial écrase le sérieux des affaires.', 1),
    ('3a8070c9-0cd2-56f1-8f23-f5b82b63ff43'::uuid, '9c71054b-dad3-5672-870d-0ec07504a17d'::uuid, 'Qu’est-ce qui interrompt constamment la négociation ?', 'mcq', '["La querelle domestique autour de la purge de Toto","Un incendie","L’arrivée de créanciers","Une panne de courant"]'::jsonb, 0, 'Julie entre en peignoir et en pantoufles.', 2),
    ('e697b601-5ff2-5b89-b189-f1abab14f7ff'::uuid, '9c71054b-dad3-5672-870d-0ec07504a17d'::uuid, 'Qui finit par boire la purge ?', 'mcq', '["Chouilloux, le fonctionnaire, par méprise","Toto seulement","Follavoine","Personne"]'::jsonb, 0, 'Le marché est perdu du même coup.', 3),
    ('465b1df8-c7a3-54bf-9c30-54ee44c9df53'::uuid, '9c71054b-dad3-5672-870d-0ec07504a17d'::uuid, 'À quelle série la pièce appartient-elle ?', 'mcq', '["Du mariage au divorce","Les Fiancés de Loches","Le Théâtre en liberté","Les Farces de province"]'::jsonb, 0, 'Feydeau y quitte le vaudeville d’hôtel pour le huis clos conjugal.', 4),
    ('48df70f5-68f1-517f-929d-c70cefaec22e'::uuid, '9c71054b-dad3-5672-870d-0ec07504a17d'::uuid, 'D’où naît le comique de la pièce ?', 'mcq', '["Du décalage entre le sérieux des affaires et la trivialité domestique","De déguisements","De quiproquos d’identité","De jeux de mots savants"]'::jsonb, 0, 'Le dialogue conjugal y est d’une brutalité admirée par Ionesco.', 5),
    ('364e99b0-9d11-5314-90a4-6fcbfb642f0e'::uuid, '9c71054b-dad3-5672-870d-0ec07504a17d'::uuid, 'La pièce comporte plusieurs actes et de nombreux décors.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un seul acte, un seul salon, une matinée.', 6),
    ('24b9b834-8a4b-5ce5-b19b-e15ed64923e8'::uuid, '16fb214f-4028-5306-8065-9d20ed3bfb7e'::uuid, 'Quel livre du cycle a été publié en premier ?', 'mcq', '["Pantagruel, en 1532","Gargantua","Le Tiers Livre","Le Quart Livre"]'::jsonb, 0, 'Gargantua, qui raconte le père, paraît deux ans plus tard.', 1),
    ('d5a9a437-6e86-507b-8778-24634ee0e45e'::uuid, '16fb214f-4028-5306-8065-9d20ed3bfb7e'::uuid, 'Qui est Panurge ?', 'mcq', '["Le compagnon rusé, menteur et lâche de Pantagruel","Le précepteur du géant","Un roi ennemi","Le frère de Gargantua"]'::jsonb, 0, 'Il deviendra le personnage central du Tiers Livre.', 2),
    ('39cf016b-deb9-5ed6-9166-6d75c41c5be1'::uuid, '16fb214f-4028-5306-8065-9d20ed3bfb7e'::uuid, 'Quel texte contient le programme humaniste ?', 'mcq', '["La lettre de Gargantua à son fils","Le prologue","Le procès de Baisecul","Le chapitre des Dipsodes"]'::jsonb, 0, '« Science sans conscience n’est que ruine de l’âme. »', 3),
    ('d464f8e6-20b3-5971-ac35-47567ee3d83b'::uuid, '16fb214f-4028-5306-8065-9d20ed3bfb7e'::uuid, 'Que ridiculise l’épisode de l’écolier limousin ?', 'mcq', '["Un français latinisé et prétentieux","L’accent provincial","Les mauvaises universités","L’ignorance du peuple"]'::jsonb, 0, 'Rabelais défend une langue vivante contre le jargon.', 4),
    ('cf51cfce-fae4-51b0-8674-297d62e1c6e4'::uuid, '16fb214f-4028-5306-8065-9d20ed3bfb7e'::uuid, 'Contre qui Pantagruel fait-il la guerre ?', 'mcq', '["Les Dipsodes et le géant Loup-Garou","Les Anglais","Picrochole","Les Turcs"]'::jsonb, 0, 'La parodie épique y est constante.', 5),
    ('097759eb-0531-5191-b7cb-3c04a7f95519'::uuid, '16fb214f-4028-5306-8065-9d20ed3bfb7e'::uuid, 'Le livre fut approuvé par les autorités religieuses.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il fut condamné par la Sorbonne, comme la plupart des livres de Rabelais.', 6),
    ('7d08f044-6dea-5de9-bd2a-bd723cd8d1b8'::uuid, '11ad5386-ccf7-5e30-8baf-f7e917d7c50c'::uuid, 'Quel événement déclenche l’intrigue ?', 'mcq', '["Un héritage laissé au seul fils cadet","Un naufrage","La mort du père","Un mariage annoncé"]'::jsonb, 0, 'Maréchal lègue toute sa fortune à Jean.', 1),
    ('ca7537e9-c876-5c29-89fb-5b5ad3c9d3a7'::uuid, '11ad5386-ccf7-5e30-8baf-f7e917d7c50c'::uuid, 'Que découvre Pierre par déduction ?', 'mcq', '["Que Jean est le fils de Maréchal","Que son père est ruiné","Que Jean est adopté","Que Maréchal était son oncle"]'::jsonb, 0, 'Un portrait disparu et des dates suffisent.', 2),
    ('0f07c748-371c-5619-b521-2da60c6f38d1'::uuid, '11ad5386-ccf7-5e30-8baf-f7e917d7c50c'::uuid, 'Comment Pierre agit-il après sa découverte ?', 'mcq', '["Il la fait comprendre à sa mère, puis s’embarque comme médecin de bord","Il porte plainte","Il tue Jean en duel","Il se tait définitivement"]'::jsonb, 0, 'Sa famille le regarde partir avec soulagement.', 3),
    ('a70adb00-180e-51eb-9c2c-63b68c2d0f64'::uuid, '11ad5386-ccf7-5e30-8baf-f7e917d7c50c'::uuid, 'Quelle est la particularité de la construction du roman ?', 'mcq', '["Tout se joue dans le regard et le soupçon, sans événement extérieur","Il alterne plusieurs narrateurs","Il est écrit en lettres","Il couvre trente ans"]'::jsonb, 0, 'C’est un modèle de roman court.', 4),
    ('b46b0ae1-8ead-52d3-a834-a78d253ed360'::uuid, '11ad5386-ccf7-5e30-8baf-f7e917d7c50c'::uuid, 'Que contient la préface du roman ?', 'mcq', '["La théorie de Maupassant sur le roman et l’illusion du vrai","Une dédicace à Flaubert","Un résumé de l’intrigue","Une réponse à la critique"]'::jsonb, 0, '« Faire vrai consiste à donner l’illusion complète du vrai. »', 5),
    ('555d5afa-8389-5f7a-ae33-cf4051dcb105'::uuid, '11ad5386-ccf7-5e30-8baf-f7e917d7c50c'::uuid, 'Le père Roland comprend la situation en même temps que Pierre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il ne s’étonne de rien : son aveuglement est un ressort du roman.', 6),
    ('3214bfa6-6863-5292-a45d-bf012bc2b23e'::uuid, 'c7ce626a-dc40-5bbb-9ced-b73ca7fcadf5'::uuid, 'Quel mouvement ce recueil inaugure-t-il ?', 'mcq', '["Le Parnasse","Le symbolisme","Le romantisme","Le naturalisme"]'::jsonb, 0, 'Leconte de Lisle en devient le chef de file.', 1),
    ('d00d89ff-07c1-5a03-bd9d-1ee56014bca1'::uuid, 'c7ce626a-dc40-5bbb-9ced-b73ca7fcadf5'::uuid, 'Que condamne la préface ?', 'mcq', '["Le lyrisme personnel et « l’étalage des plaies du cœur »","La poésie savante","L’Antiquité","La rime riche"]'::jsonb, 0, 'Elle réclame une poésie impersonnelle.', 2),
    ('d62c04f9-95fa-5c10-abe7-c4aba693681f'::uuid, 'c7ce626a-dc40-5bbb-9ced-b73ca7fcadf5'::uuid, 'Quelles sources d’inspiration le recueil mobilise-t-il ?', 'mcq', '["La Grèce antique et la mythologie indienne","Le Moyen Âge chrétien","La Renaissance italienne","Le folklore breton"]'::jsonb, 0, 'Leconte de Lisle puise dans les textes sanskrits récemment traduits.', 3),
    ('728ba0ba-0ee0-5876-b518-2d29d62f1f0d'::uuid, 'c7ce626a-dc40-5bbb-9ced-b73ca7fcadf5'::uuid, 'De quelle île l’auteur est-il originaire ?', 'mcq', '["La Réunion","La Martinique","La Corse","Madagascar"]'::jsonb, 0, 'Des poèmes créoles s’y rattachent.', 4),
    ('43b20300-e9f1-52f5-af7f-59d159c0b875'::uuid, 'c7ce626a-dc40-5bbb-9ced-b73ca7fcadf5'::uuid, 'Quels sont les trois principes du Parnasse ?', 'mcq', '["Impersonnalité, érudition, culte de la forme","Sincérité, spontanéité, engagement","Rêve, hasard, inconscient","Observation, document, hérédité"]'::jsonb, 0, 'La poésie doit être un art objectif, comme la sculpture.', 5),
    ('a9990f50-a644-542b-9be1-5045d8f31976'::uuid, 'c7ce626a-dc40-5bbb-9ced-b73ca7fcadf5'::uuid, 'Le Parnasse a été prolongé sans contestation par les symbolistes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils lui reprocheront précisément sa froideur et son impersonnalité.', 6),
    ('892244bb-9d31-59e5-b6a9-5029f502dd36'::uuid, '775d05bd-020a-5233-83e3-578a4fb14bd8'::uuid, 'D’où vient le titre du recueil ?', 'mcq', '["De Saturne, planète des mélancoliques","D’un poème de Baudelaire","D’un lieu-dit","D’un mot inventé"]'::jsonb, 0, 'Les « saturniens » sont nés sous une mauvaise étoile.', 1),
    ('79f66438-5cb3-5986-a629-9029a3bdb526'::uuid, '775d05bd-020a-5233-83e3-578a4fb14bd8'::uuid, 'Quel poème commence par « Les sanglots longs des violons » ?', 'mcq', '["Chanson d’automne","Mon rêve familier","Nevermore","Soleils couchants"]'::jsonb, 0, 'Il est devenu l’un des poèmes les plus connus de la langue.', 2),
    ('c0a7409e-ceed-5ccd-9770-e93491ba8299'::uuid, '775d05bd-020a-5233-83e3-578a4fb14bd8'::uuid, 'Quelle qualité Verlaine privilégie-t-il ?', 'mcq', '["La musicalité","L’érudition","La précision descriptive","L’engagement"]'::jsonb, 0, '« De la musique avant toute chose », dira son Art poétique.', 3),
    ('cf30bb3f-d1bc-5813-85d6-240774faeff0'::uuid, '775d05bd-020a-5233-83e3-578a4fb14bd8'::uuid, 'Quel type de vers Verlaine affectionne-t-il ?', 'mcq', '["Le vers impair","L’alexandrin exclusivement","Le vers libre","Le décasyllabe seul"]'::jsonb, 0, 'Il brise ainsi le rythme attendu.', 4),
    ('fc46b6d9-a9e4-5f1f-ae12-dbb6f98d0224'::uuid, '775d05bd-020a-5233-83e3-578a4fb14bd8'::uuid, 'Quel mouvement ce recueil annonce-t-il ?', 'mcq', '["Le symbolisme","Le naturalisme","Le surréalisme","Le classicisme"]'::jsonb, 0, 'Suggérer plutôt que décrire.', 5),
    ('1222d0a7-ea41-5d59-b402-c003cfb5951f'::uuid, '775d05bd-020a-5233-83e3-578a4fb14bd8'::uuid, 'Verlaine avait plus de quarante ans lors de cette publication.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il avait vingt-deux ans, et publiait à compte d’auteur.', 6),
    ('aeb1ff69-924a-5504-915e-3e2242219348'::uuid, '581d2b62-1744-5d77-b26f-b57968264aa6'::uuid, 'Quelle est la formule qui résume la poétique de Mallarmé ?', 'mcq', '["« Peindre non la chose, mais l’effet qu’elle produit »","« De la musique avant toute chose »","« Il faut être absolument moderne »","« La beauté sera convulsive »"]'::jsonb, 0, 'Le poème suggère au lieu de décrire.', 1),
    ('e6c6d1ea-8f91-56ab-a1f9-bada2e17c482'::uuid, '581d2b62-1744-5d77-b26f-b57968264aa6'::uuid, 'Quel poème commence par « La chair est triste, hélas ! » ?', 'mcq', '["Brise marine","L’Azur","Apparition","Sainte"]'::jsonb, 0, '« … et j’ai lu tous les livres. »', 2),
    ('5da69382-b85e-5795-8419-273dd32f5eeb'::uuid, '581d2b62-1744-5d77-b26f-b57968264aa6'::uuid, 'Quelle œuvre musicale s’inspire de son églogue ?', 'mcq', '["Le Prélude à l’après-midi d’un faune de Debussy","Le Sacre du printemps","Pelléas et Mélisande","La Mer"]'::jsonb, 0, 'Créé en 1894.', 3),
    ('f047d794-cded-58a8-ba85-9b7936042ed9'::uuid, '581d2b62-1744-5d77-b26f-b57968264aa6'::uuid, 'Qu’est-ce que le « Livre » chez Mallarmé ?', 'mcq', '["Un ouvrage absolu qui contiendrait tout, jamais réalisé","Son unique recueil publié","Un journal intime","Un traité de poétique"]'::jsonb, 0, 'Il n’en a laissé que des notes et des fragments.', 4),
    ('ce24fb76-f340-5839-9262-dfea3adc7c6b'::uuid, '581d2b62-1744-5d77-b26f-b57968264aa6'::uuid, 'Quelle innovation apporte Un coup de dés ?', 'mcq', '["La mise en page devient un moyen poétique","La suppression des rimes","L’usage du vers libre","L’écriture automatique"]'::jsonb, 0, 'Le texte y éclate sur la double page.', 5),
    ('c8e2d19f-7273-5d00-922b-6f262db468de'::uuid, '581d2b62-1744-5d77-b26f-b57968264aa6'::uuid, 'Mallarmé a laissé une œuvre poétique très abondante.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Son œuvre est mince, et son influence immense.', 6),
    ('72bd198b-577b-53a2-befe-7428d235e1fb'::uuid, '86a40e65-5517-5611-b010-63215a447a89'::uuid, 'Que fait Polyeucte après son baptême ?', 'mcq', '["Il brise les idoles en plein sacrifice public","Il fuit la ville","Il convertit Pauline","Il renonce à son titre"]'::jsonb, 0, 'Le geste le condamne à mort.', 1),
    ('1e093e6c-801d-5ebf-8a64-ee97fb000a3e'::uuid, '86a40e65-5517-5611-b010-63215a447a89'::uuid, 'Qui est Sévère ?', 'mcq', '["Le chevalier romain que Pauline avait aimé et croyait mort","Le père de Pauline","L’ami chrétien de Polyeucte","L’empereur"]'::jsonb, 0, 'Il reparaît victorieux et favori de l’empereur.', 2),
    ('4b3d171e-e1d3-5a55-84f1-e66a38ed27ce'::uuid, '86a40e65-5517-5611-b010-63215a447a89'::uuid, 'Que fait Polyeucte de son épouse avant de mourir ?', 'mcq', '["Il la cède à Sévère","Il l’emmène avec lui","Il la répudie par colère","Il lui demande d’abjurer"]'::jsonb, 0, 'Le geste, très commenté, marque le renoncement au monde.', 3),
    ('09f4e687-a9d3-5d33-8611-44fe42428ed4'::uuid, '86a40e65-5517-5611-b010-63215a447a89'::uuid, 'Quel effet produit son martyre ?', 'mcq', '["La conversion de Pauline puis de Félix","Une révolte populaire","La fin des persécutions dans tout l’Empire","Rien du tout"]'::jsonb, 0, 'Sévère promet de protéger les chrétiens.', 4),
    ('79185a87-7c04-516e-846f-3d534ce2f9b1'::uuid, '86a40e65-5517-5611-b010-63215a447a89'::uuid, 'Quel débat théologique la pièce touche-t-elle ?', 'mcq', '["Le rapport entre la volonté humaine et la grâce divine","La querelle des images","Le célibat des prêtres","La prédestination calviniste seule"]'::jsonb, 0, 'Question très vive dans la France du XVIIe siècle.', 5),
    ('ee8151a2-b381-5361-9a89-f2d846a1320d'::uuid, '86a40e65-5517-5611-b010-63215a447a89'::uuid, 'Polyeucte quitte Pauline par indifférence.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« Je vous aime… mais bien plus que moi-même » : il a trouvé plus grand, non moins.', 6),
    ('4416fa4d-b15b-5008-8d9e-04131006242d'::uuid, '5f1151ef-1fd8-5963-b87e-423527d7fc4e'::uuid, 'Combien de personnages principaux la pièce compte-t-elle ?', 'mcq', '["Deux, H1 et H2","Trois","Quatre","Un seul"]'::jsonb, 0, 'Des voisins interviennent brièvement.', 1),
    ('ca134e7b-a11e-5b91-8f66-aa4f8d76f5a3'::uuid, '5f1151ef-1fd8-5963-b87e-423527d7fc4e'::uuid, 'Quelle phrase déclenche la rupture ?', 'mcq', '["« C’est bien… ça »","« Tu as changé »","« Je ne t’aime plus »","« Tu as réussi »"]'::jsonb, 0, 'Ce n’est pas la phrase, c’est la suspension et le ton.', 2),
    ('9f45fb93-5ba1-5855-8e0b-8d2b040e980f'::uuid, '5f1151ef-1fd8-5963-b87e-423527d7fc4e'::uuid, 'Qu’appelle-t-on tropismes chez Sarraute ?', 'mcq', '["Les mouvements intérieurs infimes qui précèdent la parole","Les didascalies","Les répliques brèves","Les silences notés"]'::jsonb, 0, 'Le mot vient de la biologie.', 3),
    ('7ff19f61-ecec-581c-b46c-36d8deef029a'::uuid, '5f1151ef-1fd8-5963-b87e-423527d7fc4e'::uuid, 'Quelle blessure la dispute révèle-t-elle ?', 'mcq', '["La condescendance et l’écart social","Une trahison amoureuse","Un conflit d’héritage","Un mensonge ancien"]'::jsonb, 0, 'La vie « réussie » de l’un contre la vie « ratée » de l’autre.', 4),
    ('901e9320-9e53-55f5-af86-321c6c1be756'::uuid, '5f1151ef-1fd8-5963-b87e-423527d7fc4e'::uuid, 'Qu’est-ce qui porte le sens dans le texte ?', 'mcq', '["Les silences et les phrases inachevées","Les longues tirades","Les didascalies détaillées","Le décor"]'::jsonb, 0, 'Le comédien y travaille le souffle autant que la parole.', 5),
    ('ab4e48ef-ba01-50c6-b1ad-95b4ae4da3b8'::uuid, '5f1151ef-1fd8-5963-b87e-423527d7fc4e'::uuid, 'La pièce se termine par une réconciliation.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La rupture est consommée, sans qu’aucun fait ne l’explique.', 6),
    ('05688960-b010-5139-85ae-2efc3fb2cbf9'::uuid, 'cca79f1b-f6e7-5def-bb77-9d3c6c835563'::uuid, 'Que préface ce texte ?', 'mcq', '["Cromwell, une pièce de plus de six mille vers, injouable","Hernani","Ruy Blas","Les Contemplations"]'::jsonb, 0, 'La préface est bien plus lue que la pièce.', 1),
    ('9263fa43-7c0c-5597-92e1-44ea52f59c04'::uuid, 'cca79f1b-f6e7-5def-bb77-9d3c6c835563'::uuid, 'Quels sont les trois âges de la poésie selon Hugo ?', 'mcq', '["L’ode, l’épopée, le drame","La tragédie, la comédie, la farce","Le classique, le baroque, le moderne","L’épique, le lyrique, le didactique"]'::jsonb, 0, 'Le drame correspond aux temps modernes et au christianisme.', 2),
    ('353f029b-fb11-54cf-ac30-4bd0cd07410c'::uuid, 'cca79f1b-f6e7-5def-bb77-9d3c6c835563'::uuid, 'Que doit unir l’art moderne ?', 'mcq', '["Le sublime et le grotesque","Le vrai et le beau","Le rire et les larmes seulement","Le vers et la prose"]'::jsonb, 0, 'Le grotesque fait ressortir le beau par contraste.', 3),
    ('e0c6787c-e934-552e-ac42-6570ba8b78e5'::uuid, 'cca79f1b-f6e7-5def-bb77-9d3c6c835563'::uuid, 'Quelles règles Hugo veut-il abolir ?', 'mcq', '["Les unités de temps et de lieu, la séparation des genres","L’unité d’action","L’usage du vers","La division en actes"]'::jsonb, 0, 'Il conserve en revanche l’unité d’action.', 4),
    ('3c223bfc-0ec2-50d4-a4a7-33492c1be1cf'::uuid, 'cca79f1b-f6e7-5def-bb77-9d3c6c835563'::uuid, 'Quelle pièce le manifeste prépare-t-il ?', 'mcq', '["Hernani, créée en 1830","Lorenzaccio","Ruy Blas","Les Burgraves"]'::jsonb, 0, 'Et la bataille qui l’accompagne.', 5),
    ('68bb82a7-1a66-5f91-b1c1-2ca6d1191c45'::uuid, 'cca79f1b-f6e7-5def-bb77-9d3c6c835563'::uuid, 'La préface ne concerne que le théâtre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle justifie tout le romantisme français, roman compris.', 6),
    ('9318183d-45d6-5ea4-808a-b7beeffbbaf5'::uuid, '8fd0f0b9-b5a9-592c-8096-ccb9f68e9a34'::uuid, 'À quel âge Musset publie-t-il ses premiers poèmes ?', 'mcq', '["Dix-neuf ans","Trente ans","Vingt-cinq ans","Quinze ans"]'::jsonb, 0, 'Les Contes d’Espagne et d’Italie paraissent en 1829.', 1),
    ('4c93581d-9311-55a9-ac98-fd46b58d2824'::uuid, '8fd0f0b9-b5a9-592c-8096-ccb9f68e9a34'::uuid, 'Quel poème fit scandale par sa comparaison de la lune ?', 'mcq', '["Ballade à la lune","Rolla","Namouna","La Nuit de mai"]'::jsonb, 0, 'La lune y est comparée au point sur un i.', 2),
    ('7e4a6468-314e-5921-b334-abdce6a29306'::uuid, '8fd0f0b9-b5a9-592c-8096-ccb9f68e9a34'::uuid, 'Quelle attitude Musset adopte-t-il face au romantisme ?', 'mcq', '["Il le prend au sérieux tout en s’en moquant","Il le rejette totalement","Il le défend sans nuance","Il l’ignore"]'::jsonb, 0, 'Digressions, adresses au lecteur, ironie mêlée à la passion.', 3),
    ('482671ae-261c-5ea7-b426-266193755dde'::uuid, '8fd0f0b9-b5a9-592c-8096-ccb9f68e9a34'::uuid, 'Quelle formule résume son refus de l’imitation ?', 'mcq', '["« Mon verre n’est pas grand, mais je bois dans mon verre »","« Je mis un bonnet rouge au vieux dictionnaire »","« Il faut être absolument moderne »","« Ô temps, suspends ton vol »"]'::jsonb, 0, 'Elle est devenue proverbiale.', 4),
    ('01a3ada8-6c1b-59f2-ac19-42bdb63c9ebf'::uuid, '8fd0f0b9-b5a9-592c-8096-ccb9f68e9a34'::uuid, 'Quelle œuvre suit ces Premières poésies ?', 'mcq', '["Les Nuits, écrites après la rupture avec George Sand","Les Contemplations","Les Fleurs du mal","Les Destinées"]'::jsonb, 0, 'Le lyrisme y devient grave.', 5),
    ('c621d133-eecb-5a3d-a7d2-fd76d9385e50'::uuid, '8fd0f0b9-b5a9-592c-8096-ccb9f68e9a34'::uuid, 'Musset partage la solennité de Hugo.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il s’en démarque nettement, par l’ironie et la légèreté affichée.', 6),
    ('45245f94-8caa-5f25-b8cf-e45a1f5dfbd9'::uuid, '8f880704-c11b-5727-8913-d15c7836c7e2'::uuid, 'Quand ces brochures ont-elles été publiées ?', 'mcq', '["En 1823 et 1825, avant la Préface de Cromwell","En 1830","En 1840","En 1810"]'::jsonb, 0, 'Stendhal devance donc Hugo.', 1),
    ('1170ea8b-1d16-521c-a5ee-b084baa7a3b4'::uuid, '8f880704-c11b-5727-8913-d15c7836c7e2'::uuid, 'Comment Stendhal définit-il le romantisme ?', 'mcq', '["L’art de donner aux contemporains le plus de plaisir possible","Une école littéraire allemande","Le culte du Moyen Âge","Le refus de toute règle"]'::jsonb, 0, 'Le classicisme donne le plaisir des arrière-grands-pères.', 2),
    ('c266f623-bfac-5d97-923a-85dd24c89429'::uuid, '8f880704-c11b-5727-8913-d15c7836c7e2'::uuid, 'Quelle conséquence en tire-t-il pour Racine ?', 'mcq', '["Racine était romantique en son temps","Racine doit être imité à la lettre","Racine est illisible","Racine était classique par nature"]'::jsonb, 0, 'La relativité du goût est le cœur de sa thèse.', 3),
    ('aa10e2c7-2e0a-552b-9c9d-b7094eafee9f'::uuid, '8f880704-c11b-5727-8913-d15c7836c7e2'::uuid, 'Quelles réformes propose-t-il pour la tragédie ?', 'mcq', '["Abandonner les unités, écrire en prose, prendre des sujets nationaux","Revenir au grec","Supprimer les actes","Écrire pour la lecture seule"]'::jsonb, 0, 'Il propose d’imiter Shakespeare sans le copier.', 4),
    ('e63e19a5-0833-5815-a263-ce2a470388ee'::uuid, '8f880704-c11b-5727-8913-d15c7836c7e2'::uuid, 'Quel événement parisien nourrit la polémique ?', 'mcq', '["Une troupe anglaise jouant Shakespeare, huée par le public","La création d’Hernani","La censure d’une pièce de Hugo","La mort de Talma"]'::jsonb, 0, 'La querelle était donc très concrète.', 5),
    ('0cc3925d-f9eb-57ae-99f5-aea3e5dc3fec'::uuid, '8f880704-c11b-5727-8913-d15c7836c7e2'::uuid, 'Le texte défend l’idée d’un beau éternel et universel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il pose au contraire la relativité historique du goût.', 6),
    ('ea379757-2aae-5ae5-b35b-98cd68258dce'::uuid, '30693152-e705-56ec-a704-d23869195b25'::uuid, 'Combien de maximes le recueil contient-il environ ?', 'mcq', '["Cinq cents","Cinquante","Deux mille","Cent"]'::jsonb, 0, 'Retravaillées de 1665 à 1678.', 1),
    ('cec2ccaa-d9f4-5938-9dd2-8bd2191b1cd9'::uuid, '30693152-e705-56ec-a704-d23869195b25'::uuid, 'Quelle est la thèse centrale du livre ?', 'mcq', '["Nos vertus ne sont souvent que des vices déguisés","La vertu est naturelle à l’homme","La raison gouverne les passions","Le bonheur est accessible à tous"]'::jsonb, 0, 'L’amour-propre se cache derrière chaque conduite.', 2),
    ('4c9c8ebe-80b1-5838-b5ad-acbb60eb579a'::uuid, '30693152-e705-56ec-a704-d23869195b25'::uuid, 'Où est née la pratique de la maxime chez La Rochefoucauld ?', 'mcq', '["Dans les jeux de salon de Madame de Sablé","À l’Académie française","À la cour du roi","Dans un monastère"]'::jsonb, 0, 'On s’y exerçait à formuler des sentences.', 3),
    ('4636420e-7a2e-50f7-b039-fbe18a94f43c'::uuid, '30693152-e705-56ec-a704-d23869195b25'::uuid, 'Quelle est la forme typique d’une maxime ?', 'mcq', '["Brève, souvent construite sur une antithèse ou une chute","Longue et démonstrative","Dialoguée","Versifiée"]'::jsonb, 0, 'La concision est la condition de l’effet.', 4),
    ('e56568ce-e7ac-5062-8677-bda3f0f23b5e'::uuid, '30693152-e705-56ec-a704-d23869195b25'::uuid, 'À quel courant religieux son pessimisme est-il rapproché ?', 'mcq', '["Le jansénisme","Le protestantisme","Le quiétisme","Le gallicanisme"]'::jsonb, 0, 'La grâce y manque, et l’homme est livré à son amour-propre.', 5),
    ('b8321df2-23ed-5648-a3f2-537c7be82bf4'::uuid, '30693152-e705-56ec-a704-d23869195b25'::uuid, 'La Rochefoucauld prêche une morale édifiante.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il observe et démonte, sans prêcher : c’est un moraliste, non un moralisateur.', 6),
    ('a483b51d-4645-5d62-8231-a5d50755a157'::uuid, '7331dcb8-edc6-55cb-bc99-6be9f25d4bf1'::uuid, 'Comment Aristote définit-il la rhétorique ?', 'mcq', '["La faculté de découvrir ce qui est propre à persuader","L’art de mentir avec élégance","La science du beau langage","L’étude des figures de style"]'::jsonb, 0, 'C’est une technique neutre, dont l’usage peut être bon ou mauvais.', 1),
    ('a21861b6-2e4f-57d7-b080-859e5405a6d6'::uuid, '7331dcb8-edc6-55cb-bc99-6be9f25d4bf1'::uuid, 'Quels sont les trois moyens de persuasion ?', 'mcq', '["Ethos, pathos, logos","Invention, disposition, élocution","Judiciaire, délibératif, épidictique","Thèse, antithèse, synthèse"]'::jsonb, 0, 'Le caractère, les émotions et le raisonnement.', 2),
    ('da204dc5-3f6f-5cea-96b4-8038443d305c'::uuid, '7331dcb8-edc6-55cb-bc99-6be9f25d4bf1'::uuid, 'Qu’est-ce que l’ethos ?', 'mcq', '["L’image que l’orateur donne de lui-même","L’émotion suscitée","Le raisonnement employé","Le style de la période"]'::jsonb, 0, 'Honnêteté, compétence, bienveillance.', 3),
    ('2b8d5547-7188-5ff9-b83f-3024d50a289d'::uuid, '7331dcb8-edc6-55cb-bc99-6be9f25d4bf1'::uuid, 'Quel genre oratoire porte sur l’avenir ?', 'mcq', '["Le délibératif","Le judiciaire","L’épidictique","Le narratif"]'::jsonb, 0, 'Il s’agit de conseiller ou de déconseiller.', 4),
    ('e99a53fb-d306-5442-84d0-0dcf0a055cdb'::uuid, '7331dcb8-edc6-55cb-bc99-6be9f25d4bf1'::uuid, 'Qu’est-ce qu’un enthymème ?', 'mcq', '["Un syllogisme abrégé, dont une prémisse est sous-entendue","Une figure de style","Un exemple historique","Une conclusion sans preuve"]'::jsonb, 0, 'C’est la forme courante du raisonnement dans le discours.', 5),
    ('dafb0d03-7129-51fa-86b0-ffb5cfeb2c28'::uuid, '7331dcb8-edc6-55cb-bc99-6be9f25d4bf1'::uuid, 'Ce vocabulaire est encore utilisé pour analyser les textes argumentatifs.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ethos, pathos et logos structurent toujours l’étude de l’argumentation.', 6),
    ('43db490d-221b-5a33-b1f2-dc995ddaf15e'::uuid, 'f868d87b-bd0b-5dcb-b9c7-23718cb73eee'::uuid, 'Que devient la population de la ville ?', 'mcq', '["Elle se métamorphose en rhinocéros","Elle fuit la ville","Elle se révolte","Elle tombe malade"]'::jsonb, 0, 'Chacun trouve une bonne raison de se transformer.', 1),
    ('deb502ec-a183-5f3c-a483-289c4501eb18'::uuid, 'f868d87b-bd0b-5dcb-b9c7-23718cb73eee'::uuid, 'Quel personnage se transforme sous les yeux du spectateur ?', 'mcq', '["Jean","Daisy","Bérenger","Le Logicien"]'::jsonb, 0, 'Il défend peu à peu la rhinocérite au cours de la scène.', 2),
    ('5559796f-c296-50e1-a24f-10eea559ca6b'::uuid, 'f868d87b-bd0b-5dcb-b9c7-23718cb73eee'::uuid, 'Pourquoi Bérenger résiste-t-il ?', 'mcq', '["Parce qu’il ne peut pas se transformer, non par héroïsme","Par courage politique","Par conviction religieuse","Parce qu’il est protégé"]'::jsonb, 0, 'Sa faiblesse même le sauve.', 3),
    ('d8201c7d-c1b1-5d4f-aa55-e1ba6dc09416'::uuid, 'f868d87b-bd0b-5dcb-b9c7-23718cb73eee'::uuid, 'Que devient Daisy ?', 'mcq', '["Elle cède et se transforme à son tour","Elle reste avec Bérenger","Elle quitte la ville","Elle disparaît sans explication"]'::jsonb, 0, 'Bérenger reste seul.', 4),
    ('3279f4f8-5fa9-5b81-8aa0-5e1b7963968e'::uuid, 'f868d87b-bd0b-5dcb-b9c7-23718cb73eee'::uuid, 'De quoi la pièce est-elle l’allégorie ?', 'mcq', '["Des totalitarismes et du conformisme idéologique","De l’épidémie","De la guerre coloniale","De la crise économique"]'::jsonb, 0, 'Ionesco avait vu la montée du fascisme roumain.', 5),
    ('e5448e6c-f556-58a7-88f0-285f0c1d2cd5'::uuid, 'f868d87b-bd0b-5dcb-b9c7-23718cb73eee'::uuid, 'Bérenger finit par se transformer.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il essaie, échoue, et conclut : « Je ne capitule pas ! »', 6),
    ('f8fc05ef-2b44-52dd-b13e-223ecb7ef253'::uuid, 'e153f748-731e-579f-bf9c-cbe06445308e'::uuid, 'Dans quelles circonstances le recueil paraît-il ?', 'mcq', '["Pendant l’emprisonnement de Verlaine à Mons","À son retour à Paris","Après la mort de Rimbaud","Avant sa rencontre avec Rimbaud"]'::jsonb, 0, 'Il avait tiré sur Rimbaud à Bruxelles.', 1),
    ('db693778-b489-5bd3-bb00-68b9e50ec0c2'::uuid, 'e153f748-731e-579f-bf9c-cbe06445308e'::uuid, 'D’où vient le titre du recueil ?', 'mcq', '["De mélodies sans texte de Mendelssohn","D’un poème de Baudelaire","D’une chanson populaire","D’un roman anglais"]'::jsonb, 0, 'Il annonce une poésie où le sens s’efface devant la musique.', 2),
    ('b0316e87-c0c0-5292-9284-b4414d90ab26'::uuid, 'e153f748-731e-579f-bf9c-cbe06445308e'::uuid, 'Quel vers célèbre ouvre l’une des Ariettes ?', 'mcq', '["« Il pleure dans mon cœur comme il pleut sur la ville »","« Les sanglots longs des violons »","« Le ciel est par-dessus le toit »","« Je fais souvent ce rêve étrange »"]'::jsonb, 0, 'La pluie et les larmes s’y confondent.', 3),
    ('4b50e5e8-ddca-57a0-823e-0ec4b9a831f6'::uuid, 'e153f748-731e-579f-bf9c-cbe06445308e'::uuid, 'Quel type de vers Verlaine emploie-t-il ?', 'mcq', '["Des vers impairs","Uniquement l’alexandrin","Le vers libre","Le décasyllabe classique"]'::jsonb, 0, 'Cinq, sept, neuf ou onze syllabes : le rythme se déséquilibre.', 4),
    ('b95a5ddc-775b-5951-af32-8985bd0e934f'::uuid, 'e153f748-731e-579f-bf9c-cbe06445308e'::uuid, 'Que réalise le recueil ?', 'mcq', '["Un poème peut se passer d’anecdote et de message","Une poésie engagée","Un retour au Parnasse","Une satire sociale"]'::jsonb, 0, 'C’est l’un des sommets du symbolisme naissant.', 5),
    ('55026e3b-b573-5d99-ba96-32f99d14e540'::uuid, 'e153f748-731e-579f-bf9c-cbe06445308e'::uuid, 'Ce recueil a été mis en musique par des compositeurs.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Debussy et Fauré y ont puisé abondamment.', 6),
    ('2c716c67-d5ab-516d-b12c-bf26ca2f399c'::uuid, 'a9db67e4-028f-5ee5-bc69-9a5997c7af9f'::uuid, 'En combien de temps se déroule l’action ?', 'mcq', '["Environ cinq jours","Un an","Trois mois","Une journée"]'::jsonb, 0, 'La hâte est un élément essentiel de la tragédie.', 1),
    ('4c5a5e4a-8db3-5754-a2f2-ee5b09d0a77b'::uuid, 'a9db67e4-028f-5ee5-bc69-9a5997c7af9f'::uuid, 'Qui marie secrètement les deux amants ?', 'mcq', '["Frère Laurent","La nourrice","Le prince de Vérone","Le père Capulet"]'::jsonb, 0, 'Il espère réconcilier les familles.', 2),
    ('3cf6c5d1-a4bf-502c-ab31-12a3359145f4'::uuid, 'a9db67e4-028f-5ee5-bc69-9a5997c7af9f'::uuid, 'Pourquoi Roméo est-il banni ?', 'mcq', '["Il a tué Tybalt, qui venait de tuer Mercutio","Il a enlevé Juliette","Il a insulté le prince","Il a refusé un duel"]'::jsonb, 0, 'La vengeance enclenche la catastrophe.', 3),
    ('aab4d28a-1b2c-584c-9d6c-5148e97ac76c'::uuid, 'a9db67e4-028f-5ee5-bc69-9a5997c7af9f'::uuid, 'Qu’est-ce qui empêche le stratagème de réussir ?', 'mcq', '["La lettre explicative n’arrive pas à Roméo","Juliette se réveille trop tôt","Frère Laurent trahit","Pâris découvre tout"]'::jsonb, 0, 'Le hasard devient l’instrument du destin.', 4),
    ('3fbf6a0a-65dd-5489-8b67-18afd77e8fe0'::uuid, 'a9db67e4-028f-5ee5-bc69-9a5997c7af9f'::uuid, 'Que se passe-t-il après la mort des amants ?', 'mcq', '["Les deux familles se réconcilient","La guerre reprend","Le prince exile les Capulet","Rien ne change"]'::jsonb, 0, 'La réconciliation se paie de leur mort.', 5),
    ('f9d27e15-997b-5830-abca-031f6afa98c1'::uuid, 'a9db67e4-028f-5ee5-bc69-9a5997c7af9f'::uuid, 'La pièce ne mélange pas les registres.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les obscénités de Mercutio et de la nourrice voisinent avec le lyrisme des amants.', 6),
    ('c0dce265-62dd-5437-b0c9-029881d99a0a'::uuid, 'd4ca0782-e486-5815-b27d-26fb2825df4c'::uuid, 'Qui est Ruy Blas ?', 'mcq', '["Un valet qui se fait passer pour un noble","Un grand d’Espagne exilé","Un ministre corrompu","Le frère de la reine"]'::jsonb, 0, 'Don Salluste l’utilise comme instrument de vengeance.', 1),
    ('7055dfd9-d460-5a6f-8a28-7b67c54d1335'::uuid, 'd4ca0782-e486-5815-b27d-26fb2825df4c'::uuid, 'Quel poste Ruy Blas finit-il par occuper ?', 'mcq', '["Premier ministre","Capitaine des gardes","Ambassadeur","Gouverneur de province"]'::jsonb, 0, 'Et il gouverne mieux que les nobles.', 2),
    ('4f6648a8-5b75-57f6-8761-9079a03e8c8a'::uuid, 'd4ca0782-e486-5815-b27d-26fb2825df4c'::uuid, 'Quel discours célèbre prononce-t-il à l’acte III ?', 'mcq', '["« Bon appétit, messieurs ! », contre les ministres qui pillent l’Espagne","Un éloge de la reine","Une déclaration de guerre","Un plaidoyer pour son maître"]'::jsonb, 0, 'C’est le sommet politique de la pièce.', 3),
    ('3cd255af-9f04-5c31-8327-cd8f9096d339'::uuid, 'd4ca0782-e486-5815-b27d-26fb2825df4c'::uuid, 'Quel personnage assure le registre grotesque ?', 'mcq', '["Le vrai don César de Bazan, bandit truculent","La reine","Don Salluste","Le page"]'::jsonb, 0, 'Il occupe presque tout l’acte IV.', 4),
    ('ee7fff3c-f2c7-5fbc-9df9-458eff820a94'::uuid, 'd4ca0782-e486-5815-b27d-26fb2825df4c'::uuid, 'Comment la pièce se termine-t-elle ?', 'mcq', '["Ruy Blas tue Salluste, avoue tout et s’empoisonne","Il épouse la reine","Il est exilé","Salluste triomphe"]'::jsonb, 0, 'Il obtient le pardon de la reine avant de mourir.', 5),
    ('0dd874a7-226a-5557-a580-19cb89a58291'::uuid, 'd4ca0782-e486-5815-b27d-26fb2825df4c'::uuid, 'La pièce n’a aucune portée politique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Hugo y montre un homme du peuple capable de gouverner, et une société qui le lui interdit.', 6),
    ('946af60f-aaf9-50b3-9384-4108814e5193'::uuid, 'd10ef91f-22ba-52d2-8463-cb25c26a3499'::uuid, 'Où Verlaine a-t-il écrit une grande partie du recueil ?', 'mcq', '["En prison, à Mons","À Londres","Dans les Ardennes","À Paris"]'::jsonb, 0, 'Il y purgeait deux ans pour avoir tiré sur Rimbaud.', 1),
    ('3292ef3f-9d6e-548b-8e0c-0497dcfe1d71'::uuid, 'd10ef91f-22ba-52d2-8463-cb25c26a3499'::uuid, 'Quel événement personnel marque ce recueil ?', 'mcq', '["Sa conversion au catholicisme","Son mariage","La mort de son fils","Son élection"]'::jsonb, 0, 'Le repentir et la foi en deviennent les sujets.', 2),
    ('bb4c2f09-33f7-5915-8510-f8f50332d9ec'::uuid, 'd10ef91f-22ba-52d2-8463-cb25c26a3499'::uuid, 'Quel poème commence par « Le ciel est, par-dessus le toit » ?', 'mcq', '["Un poème écrit en prison","Un poème de jeunesse","Un poème d’amour","Un poème politique"]'::jsonb, 0, 'Il se termine sur « Qu’as-tu fait de ta jeunesse ? ».', 3),
    ('b99dc2af-091d-550d-ad8e-01332a0057e0'::uuid, 'd10ef91f-22ba-52d2-8463-cb25c26a3499'::uuid, 'La conversion change-t-elle la manière de Verlaine ?', 'mcq', '["Non : même simplicité, même musicalité, mêmes vers impairs","Oui, il adopte l’alexandrin classique","Oui, il devient obscur","Oui, il écrit en prose"]'::jsonb, 0, 'Seul le sujet change.', 4),
    ('d457bde3-0d04-5d14-8371-abacda4327fa'::uuid, 'd10ef91f-22ba-52d2-8463-cb25c26a3499'::uuid, 'Comment Verlaine se désignera-t-il plus tard ?', 'mcq', '["« Pauvre Lelian », anagramme de son nom","« Le poète maudit »","« Le prince des poètes »","« L’enfant perdu »"]'::jsonb, 0, 'Il s’ajoute lui-même à ses Poètes maudits.', 5),
    ('e640d286-6e19-5024-861a-b7bfa62582c1'::uuid, 'd10ef91f-22ba-52d2-8463-cb25c26a3499'::uuid, 'Le recueil a été bien accueilli par les lecteurs des Fêtes galantes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il les a déroutés : on n’attendait pas de Verlaine un livre de foi.', 6),
    ('667e543e-2544-5274-baa2-07efc71280ca'::uuid, '0b9c00b1-9e7e-59c9-84c2-2c23449c2883'::uuid, 'Où et quand Dada est-il né ?', 'mcq', '["À Zurich, en 1916, au Cabaret Voltaire","À Paris, en 1920","À Berlin, en 1918","À New York, en 1914"]'::jsonb, 0, 'Dans une ville neutre, en pleine guerre européenne.', 1),
    ('4c82edf1-c67f-5f69-a4e2-2a029f5ebce4'::uuid, '0b9c00b1-9e7e-59c9-84c2-2c23449c2883'::uuid, 'Que signifie le mot « dada » ?', 'mcq', '["Rien : il a été trouvé au hasard dans un dictionnaire","Cheval, en langage enfantin, symbole du mouvement","Un cri de guerre roumain","Une abréviation d’un manifeste"]'::jsonb, 0, 'L’absence de sens est un programme.', 2),
    ('e318c5fa-f963-5370-a1ec-f265cc245162'::uuid, '0b9c00b1-9e7e-59c9-84c2-2c23449c2883'::uuid, 'Quelle recette Tzara donne-t-il pour écrire un poème ?', 'mcq', '["Découper un article de journal et tirer les mots au hasard","Écrire sous la dictée d’un rêve","Imiter les poètes anciens","Composer en vers réguliers"]'::jsonb, 0, 'Le hasard remplace l’intention.', 3),
    ('6d25860d-b987-56b4-a1d4-e1bcf0f679bc'::uuid, '0b9c00b1-9e7e-59c9-84c2-2c23449c2883'::uuid, 'Que refuse Dada ?', 'mcq', '["L’art, la logique, la morale, le bon goût et le sens","La guerre uniquement","La peinture figurative","Le théâtre"]'::jsonb, 0, 'C’est une table rase, pas une école.', 4),
    ('6824c984-3302-578d-b82a-f643b727a903'::uuid, '0b9c00b1-9e7e-59c9-84c2-2c23449c2883'::uuid, 'Quel mouvement succède à Dada ?', 'mcq', '["Le surréalisme","Le futurisme","Le cubisme","L’expressionnisme"]'::jsonb, 0, 'Breton, d’abord dadaïste, rompra avec Tzara.', 5),
    ('017ad3e3-b955-52b2-9830-87e0d81177e8'::uuid, '0b9c00b1-9e7e-59c9-84c2-2c23449c2883'::uuid, 'Dada proposait un programme esthétique précis.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il refusait précisément tout programme : c’était une destruction, non une doctrine.', 6),
    ('1d80e78d-42ca-5d7b-8b0c-6a1344286262'::uuid, '0c8d6d43-d40a-512c-8edb-b9bc20622b9f'::uuid, 'D’où vient le titre du livre ?', 'mcq', '["De l’Évangile de Jean : « Si le grain ne meurt… »","D’un poème de Baudelaire","D’un proverbe normand","D’une lettre de Madeleine"]'::jsonb, 0, 'Il faut mourir à soi-même pour porter du fruit.', 1),
    ('0c132160-50d2-50ed-a278-cdfd20e890d1'::uuid, '0c8d6d43-d40a-512c-8edb-b9bc20622b9f'::uuid, 'Jusqu’à quand le récit va-t-il ?', 'mcq', '["Jusqu’à ses fiançailles, en 1895","Jusqu’à sa mort","Jusqu’en 1914","Jusqu’au prix Nobel"]'::jsonb, 0, 'Enfance et jeunesse seulement.', 2),
    ('755c55eb-5c86-5878-945a-1d16626aaddb'::uuid, '0c8d6d43-d40a-512c-8edb-b9bc20622b9f'::uuid, 'Quelle rencontre célèbre le livre raconte-t-il ?', 'mcq', '["Celle d’Oscar Wilde à Alger","Celle de Proust à Paris","Celle de Valéry à Montpellier","Celle de Claudel à Rome"]'::jsonb, 0, 'Wilde était accompagné de Lord Alfred Douglas.', 3),
    ('e51e2a20-39db-5859-9905-3aad59e0198f'::uuid, '0c8d6d43-d40a-512c-8edb-b9bc20622b9f'::uuid, 'Pourquoi le livre a-t-il fait scandale ?', 'mcq', '["Gide y avoue publiquement son homosexualité","Il attaque la République","Il révèle des secrets d’État","Il critique l’Église catholique"]'::jsonb, 0, 'Un geste rarissime pour l’époque.', 4),
    ('f61260c6-f951-5c84-823b-c286fcd30f7c'::uuid, '0c8d6d43-d40a-512c-8edb-b9bc20622b9f'::uuid, 'Quel milieu familial le livre décrit-il ?', 'mcq', '["Un milieu protestant austère et surveillé","Une famille catholique nombreuse","Un milieu ouvrier","Une famille d’artistes"]'::jsonb, 0, 'Interdits, culpabilité et solitude.', 5),
    ('6504438d-5a66-5266-bf93-cc12df5d7eef'::uuid, '0c8d6d43-d40a-512c-8edb-b9bc20622b9f'::uuid, 'Gide présente son autobiographie comme un exercice sans difficulté.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il doute de l’exercice : se raconter, c’est composer.', 6),
    ('c7da4a1e-8446-51ad-8e73-840fe2adb90b'::uuid, '56634329-f28e-5517-bcaa-0ecb2feafd76'::uuid, 'Quelles sont les trois parties de l’œuvre ?', 'mcq', '["Sido, Le Capitaine, Les Sauvages","La Mère, Le Jardin, Le Village","L’Enfance, Paris, Le Retour","Printemps, Été, Hiver"]'::jsonb, 0, 'Trois portraits, sans récit continu.', 1),
    ('4a4473c0-1d8b-5770-bb2b-479edb40c5b5'::uuid, '56634329-f28e-5517-bcaa-0ecb2feafd76'::uuid, 'Que découvre-t-on à la mort du Capitaine ?', 'mcq', '["Ses volumes reliés sont vierges","Il avait une seconde famille","Il était ruiné","Il avait publié sous un pseudonyme"]'::jsonb, 0, 'Seule la dédicace à sa femme est écrite.', 2),
    ('03bbc6c1-aa56-535e-bc1b-9220c5a313be'::uuid, '56634329-f28e-5517-bcaa-0ecb2feafd76'::uuid, 'Comment s’exprime la célébration chez Colette ?', 'mcq', '["Par la précision des noms et des sensations","Par l’exaltation lyrique","Par l’abstraction","Par le silence"]'::jsonb, 0, 'Pas « une fleur », mais un souci ou une pivoine.', 3),
    ('e56fe4cf-b4e5-57ad-86d9-32908fa3864f'::uuid, '56634329-f28e-5517-bcaa-0ecb2feafd76'::uuid, 'Depuis quelle position le livre est-il écrit ?', 'mcq', '["Depuis la perte : mère morte, enfance enfuie, maison vendue","Depuis le bonheur présent","Depuis l’enfance elle-même","Depuis l’exil"]'::jsonb, 0, 'C’est de là que vient la lumière du texte.', 4),
    ('3bf7dfcb-f01e-5ca1-ac29-be0e2002e112'::uuid, '56634329-f28e-5517-bcaa-0ecb2feafd76'::uuid, 'Qu’est Sido, au-delà du personnage ?', 'mcq', '["Une manière de regarder, dont naît le style de Colette","Une figure allégorique de la France","Un personnage inventé","La narratrice du livre"]'::jsonb, 0, 'Le style hérite du regard maternel.', 5),
    ('cae9e897-9cd6-584e-84b6-b89ff7bf12c4'::uuid, '56634329-f28e-5517-bcaa-0ecb2feafd76'::uuid, 'Sido est une autobiographie chronologique complète.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un récit de mémoire en trois portraits.', 6),
    ('eb3cff6c-6c57-57a7-a58f-fa55cbbc57c9'::uuid, '67c4f5b8-fffe-57f3-bf63-fc3eb400dfbe'::uuid, 'Qui est Hélène de Surgères ?', 'mcq', '["Une jeune dame d’honneur de Catherine de Médicis","La femme de Ronsard","Une paysanne d’Anjou","Une reine"]'::jsonb, 0, 'Ronsard a cinquante-quatre ans lorsqu’il lui adresse ces sonnets.', 1),
    ('a8d4cfaa-b4f6-5c51-92a4-8e33ec705b6d'::uuid, '67c4f5b8-fffe-57f3-bf63-fc3eb400dfbe'::uuid, 'Que raconte « Quand vous serez bien vieille » ?', 'mcq', '["Le poète imagine Hélène vieillie, regrettant de l’avoir dédaigné","Un adieu définitif","Un souvenir de jeunesse","Une déclaration au roi"]'::jsonb, 0, 'Elle file près du feu et s’émerveille d’avoir été chantée.', 2),
    ('094a64bc-78ab-5ae9-93b9-ee542e9c5eb8'::uuid, '67c4f5b8-fffe-57f3-bf63-fc3eb400dfbe'::uuid, 'Quelle est la chute du sonnet ?', 'mcq', '["« Cueillez dès aujourd’hui les roses de la vie »","« Ô temps, suspends ton vol »","« Mignonne, allons voir si la rose »","« La vie est brève »"]'::jsonb, 0, 'Un carpe diem devenu proverbial.', 3),
    ('10480dc3-d76e-56cd-b607-2c317d4d7335'::uuid, '67c4f5b8-fffe-57f3-bf63-fc3eb400dfbe'::uuid, 'Quel pouvoir le poème revendique-t-il ?', 'mcq', '["Celui de conserver une beauté que le temps détruit","Celui de faire la guerre","Celui de convertir","Celui de gouverner"]'::jsonb, 0, 'La poésie est la seule immortalité disponible.', 4),
    ('e90a2679-600d-5f6d-a65f-77b19f1701cd'::uuid, '67c4f5b8-fffe-57f3-bf63-fc3eb400dfbe'::uuid, 'Quel jeu le prénom d’Hélène permet-il ?', 'mcq', '["Un rapprochement avec Hélène de Troie","Un jeu de mots sur la lumière","Une allusion religieuse","Un acrostiche"]'::jsonb, 0, 'Ronsard l’exploite tout au long du recueil.', 5),
    ('5dc92ba4-3c9d-5275-8817-1ad46df156a8'::uuid, '67c4f5b8-fffe-57f3-bf63-fc3eb400dfbe'::uuid, 'Le recueil est écrit par un poète jeune et débutant.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ronsard est en fin de carrière : le décalage d’âge est au cœur du cycle.', 6),
    ('150730aa-8c55-5f73-8a39-3d967db5067d'::uuid, '9fc4f26c-8ca9-5ae9-a281-d77f23ffb411'::uuid, 'De quel texte ce Supplément est-il le prolongement ?', 'mcq', '["Le récit de voyage de Bougainville","L’Encyclopédie","Les Lettres persanes","Le Voyage en Italie"]'::jsonb, 0, 'Diderot y ajoute un dialogue critique.', 1),
    ('4e9965f4-06a9-5a7a-bee9-8b9c75c52830'::uuid, '9fc4f26c-8ca9-5ae9-a281-d77f23ffb411'::uuid, 'Quels sont les deux morceaux les plus célèbres ?', 'mcq', '["Les Adieux du vieillard et l’Entretien de l’aumônier et d’Orou","La préface et l’épilogue","Deux lettres à Sophie Volland","Deux articles de dictionnaire"]'::jsonb, 0, 'Le premier dénonce la colonisation, le second la morale sexuelle.', 2),
    ('ed0aa2c3-392d-5883-89f0-23da9999d0d7'::uuid, '9fc4f26c-8ca9-5ae9-a281-d77f23ffb411'::uuid, 'Que dénonce le vieillard tahitien ?', 'mcq', '["La prédation coloniale : « Ce pays est à toi ! Et pourquoi ? »","La religion des Tahitiens","Le commerce maritime","Les maladies apportées seulement"]'::jsonb, 0, 'La légitimité de la conquête est démontée en quelques phrases.', 3),
    ('719138c1-cb05-5089-b90d-e39385366cca'::uuid, '9fc4f26c-8ca9-5ae9-a281-d77f23ffb411'::uuid, 'Que montre l’entretien avec Orou ?', 'mcq', '["Nos mœurs sont conventionnelles, non naturelles","La supériorité de la morale chrétienne","L’égalité des religions","La nécessité du célibat"]'::jsonb, 0, 'Mariage, propriété et péché sont des institutions.', 4),
    ('4ebe8b9e-ff9e-5bad-976b-e17e2fe6b49b'::uuid, '9fc4f26c-8ca9-5ae9-a281-d77f23ffb411'::uuid, 'Que conclut Diderot ?', 'mcq', '["Suivre les lois de son pays tout en sachant qu’elles sont arbitraires","Retourner à l’état de nature","Coloniser autrement","Abolir toute loi"]'::jsonb, 0, 'La lucidité n’implique pas la révolte.', 5),
    ('959745c8-83a3-55ea-9a02-a70c72aa1ffd'::uuid, '9fc4f26c-8ca9-5ae9-a281-d77f23ffb411'::uuid, 'Le Tahiti du texte est une description ethnographique fidèle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un outil critique largement idéalisé.', 6),
    ('01db7a8b-c71a-5407-a98f-463aff3f18a9'::uuid, '92e6f832-2e69-5ec1-9d5d-fc99eed5dcbe'::uuid, 'De quelle compagnie aérienne le livre raconte-t-il les débuts ?', 'mcq', '["L’Aéropostale","Air France","La Lufthansa","La compagnie Latécoère du Pacifique"]'::jsonb, 0, 'Toulouse, l’Espagne, l’Afrique, puis l’Amérique du Sud.', 1),
    ('0a1568dc-8784-5036-a3e1-0396b64ab69a'::uuid, '92e6f832-2e69-5ec1-9d5d-fc99eed5dcbe'::uuid, 'Quel exploit de Guillaumet le livre raconte-t-il ?', 'mcq', '["Sa marche de cinq jours dans les Andes après un crash","Un vol transatlantique record","Un sauvetage en mer","Une traversée du Sahara en voiture"]'::jsonb, 0, '« Ce que j’ai fait, aucune bête ne l’aurait fait. »', 2),
    ('3c4f44ee-9257-572e-9032-83f15cc165a5'::uuid, '92e6f832-2e69-5ec1-9d5d-fc99eed5dcbe'::uuid, 'Quel accident personnel Saint-Exupéry raconte-t-il ?', 'mcq', '["Son crash dans le désert de Libye, en 1935","Un amerrissage en Méditerranée","Une panne au-dessus des Andes","Un accident à l’atterrissage à Toulouse"]'::jsonb, 0, 'Il est sauvé par un Bédouin après plusieurs jours d’errance.', 3),
    ('8f2de60d-9655-5b0e-92ae-8c69f65af197'::uuid, '92e6f832-2e69-5ec1-9d5d-fc99eed5dcbe'::uuid, 'Quelle formule résume la morale du livre ?', 'mcq', '["« Être homme, c’est précisément être responsable »","« On ne voit bien qu’avec le cœur »","« L’essentiel est invisible »","« Il faut cultiver son jardin »"]'::jsonb, 0, 'Le métier et le lien entre camarades donnent le sens.', 4),
    ('07930ee7-3c7a-5380-a4d5-672293667ad7'::uuid, '92e6f832-2e69-5ec1-9d5d-fc99eed5dcbe'::uuid, 'Quelle image clôt le livre ?', 'mcq', '["Un enfant d’émigrés endormi dans un train, « Mozart assassiné »","Un avion au décollage","Le désert au lever du jour","Un portrait de Mermoz"]'::jsonb, 0, 'C’est l’une des pages les plus citées de l’auteur.', 5),
    ('03e4c7fd-5d1c-5060-9293-c4d24f49cb23'::uuid, '92e6f832-2e69-5ec1-9d5d-fc99eed5dcbe'::uuid, 'Terre des hommes est un roman d’aventures fictif.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un récit de souvenirs et de méditations, non une fiction.', 6),
    ('bcc01aba-3652-5c83-9afc-dea6a52d431d'::uuid, '68778a29-0964-5c3c-919d-ce3f0a88ad7e'::uuid, 'Comment le roman s’ouvre-t-il ?', 'mcq', '["À la sortie du palais de justice, après un non-lieu","Le jour du mariage","Pendant l’empoisonnement","À Paris"]'::jsonb, 0, 'La famille a menti pour éviter le scandale.', 1),
    ('3a62aee9-2218-5876-afa5-d4c9a7f36222'::uuid, '68778a29-0964-5c3c-919d-ce3f0a88ad7e'::uuid, 'De quoi Thérèse est-elle accusée ?', 'mcq', '["D’avoir tenté d’empoisonner son mari à l’arsenic","D’avoir incendié la maison","D’adultère","De vol"]'::jsonb, 0, 'Elle a laissé Bernard augmenter ses doses, puis falsifié une ordonnance.', 2),
    ('ab52a92e-1589-573d-88ee-348eb9cf3965'::uuid, '68778a29-0964-5c3c-919d-ce3f0a88ad7e'::uuid, 'Où se déroule l’essentiel du roman ?', 'mcq', '["À Argelouse, dans les landes de pins","À Bordeaux","À Paris","En Bretagne"]'::jsonb, 0, 'Le paysage étouffant fait partie du drame.', 3),
    ('67a3ed3f-a326-5948-9b85-1a2bf0383ace'::uuid, '68778a29-0964-5c3c-919d-ce3f0a88ad7e'::uuid, 'Que devient Thérèse après son retour ?', 'mcq', '["Elle est séquestrée dans sa chambre","Elle est jugée à nouveau","Elle s’enfuit aussitôt","Elle est pardonnée"]'::jsonb, 0, 'Bernard sauve les apparences jusqu’au mariage d’Anne.', 4),
    ('81a281fc-83e2-5825-886c-b3345ffd24b7'::uuid, '68778a29-0964-5c3c-919d-ce3f0a88ad7e'::uuid, 'Comment le roman se termine-t-il ?', 'mcq', '["Bernard l’abandonne à Paris, ce qui est pour elle la liberté","Elle meurt","Elle retourne à Argelouse","Elle est emprisonnée"]'::jsonb, 0, 'La fin est ouverte et ambiguë.', 5),
    ('2f6ff7fb-f8b4-5ee1-b203-00f6a7f4bd4c'::uuid, '68778a29-0964-5c3c-919d-ce3f0a88ad7e'::uuid, 'Mauriac donne une explication claire du geste de Thérèse.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« Je ne sais pas ce que j’ai voulu » : l’absence de mobile est le cœur du roman.', 6),
    ('7e311d02-64ea-57d1-9aa5-8f6b98f8eaf6'::uuid, 'f42c0124-04e7-5c54-81a3-1f0d071c457d'::uuid, 'Où vit Thérèse au début du roman ?', 'mcq', '["Dans une mercerie sombre du passage du Pont-Neuf","Dans une ferme du Midi","À Saint-Ouen","Dans un hôtel particulier"]'::jsonb, 0, 'Le décor étouffant prépare le drame.', 1),
    ('823ce01b-bc11-5376-b5b3-9fb9bd46e10e'::uuid, 'f42c0124-04e7-5c54-81a3-1f0d071c457d'::uuid, 'Comment les amants tuent-ils Camille ?', 'mcq', '["Ils le noient lors d’une promenade en barque","Ils l’empoisonnent","Ils le poussent d’un toit","Ils l’étranglent"]'::jsonb, 0, 'Le crime est maquillé en accident.', 2),
    ('bcea98f5-b85a-5876-bc28-78a414a6f532'::uuid, 'f42c0124-04e7-5c54-81a3-1f0d071c457d'::uuid, 'Que se passe-t-il après leur mariage ?', 'mcq', '["Ils ne peuvent plus se toucher, hantés par le noyé","Ils sont arrêtés","Ils s’enfuient à l’étranger","Ils vivent heureux"]'::jsonb, 0, 'Insomnies, hallucinations, haine et coups.', 3),
    ('a916cb12-a9b4-57a5-b450-4c26af056cb6'::uuid, 'f42c0124-04e7-5c54-81a3-1f0d071c457d'::uuid, 'Quel est le rôle de Madame Raquin à la fin ?', 'mcq', '["Paralysée, elle comprend tout et assiste muette à leur destruction","Elle les dénonce à la police","Elle les protège","Elle meurt avant le crime"]'::jsonb, 0, 'Son regard devient un châtiment.', 4),
    ('276014f4-b692-5074-a966-94acffbd966d'::uuid, 'f42c0124-04e7-5c54-81a3-1f0d071c457d'::uuid, 'Que dit la préface de la seconde édition ?', 'mcq', '["Les personnages sont des tempéraments, étudiés comme sur des cadavres","Le roman est une fiction morale","L’auteur regrette le scandale","Le crime doit être puni par la loi"]'::jsonb, 0, 'C’est l’acte de naissance du naturalisme.', 5),
    ('b92d4f6d-1eb9-5129-9947-b5ac60b3ebd0'::uuid, 'f42c0124-04e7-5c54-81a3-1f0d071c457d'::uuid, 'Le remords des personnages est présenté comme moral.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Zola insiste : « Le remords, chez eux, fut purement physique. »', 6),
    ('a4f247bf-d70c-59d1-83f9-454c08d75252'::uuid, 'b706fe57-5cad-5df7-9813-0f28b71b59f9'::uuid, 'De quel texte le roman est-il la réécriture ?', 'mcq', '["Le Livre de Tobie, dans l’Ancien Testament","L’Odyssée","Le Livre de Job","Les Évangiles"]'::jsonb, 0, 'Il en transpose l’intrigue dans le Marais poitevin.', 1),
    ('e02ae080-d461-55ba-96a3-0e657b887fbf'::uuid, 'b706fe57-5cad-5df7-9813-0f28b71b59f9'::uuid, 'Où se déroule le roman ?', 'mcq', '["Dans le Marais poitevin contemporain","En Palestine antique","En Bretagne","À Paris"]'::jsonb, 0, 'Les eaux et les brumes du marais nourrissent l’écriture.', 2),
    ('7a61b2cb-a17b-5f5d-83c1-16bfabcd7c95'::uuid, 'b706fe57-5cad-5df7-9813-0f28b71b59f9'::uuid, 'Qui accompagne Tobie dans son voyage ?', 'mcq', '["Raphaël, un compagnon mystérieux, et un chien","Son père Théodore","Sara","Un prêtre"]'::jsonb, 0, 'La figure de l’ange n’est jamais expliquée.', 3),
    ('ee378391-c053-51e8-801a-501f9cf1e6e3'::uuid, 'b706fe57-5cad-5df7-9813-0f28b71b59f9'::uuid, 'Qu’est-il arrivé à la mère de Tobie ?', 'mcq', '["Elle a été assassinée dans des circonstances obscures","Elle est morte en couches","Elle a quitté la famille","Elle est malade"]'::jsonb, 0, 'Le père en devient inconsolable, puis aveugle.', 4),
    ('41c10af9-3255-53c6-98f6-c0c80d57df9f'::uuid, 'b706fe57-5cad-5df7-9813-0f28b71b59f9'::uuid, 'Comment le roman traite-t-il le surnaturel ?', 'mcq', '["Sans jamais l’expliquer : la lecture reste ouverte","Il le nie","Il le démontre","Il le tourne en dérision"]'::jsonb, 0, 'Le sacré est présent dans le monde ordinaire, à peine visible.', 5),
    ('fbad5fc5-e2bc-5cb6-bfb9-ec430e8f4e5e'::uuid, 'b706fe57-5cad-5df7-9813-0f28b71b59f9'::uuid, 'Le mal et la mémoire sont des thèmes constants chez Sylvie Germain.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ils traversent toute son œuvre, avec la question de la parole perdue.', 6),
    ('5fdd881b-10f2-5241-9e03-0799cd7b8d4a'::uuid, 'e05b1966-f1f7-5768-9288-0639e54ab604'::uuid, 'De quel instrument joue Monsieur de Sainte Colombe ?', 'mcq', '["La viole de gambe","Le clavecin","Le violon","Le luth"]'::jsonb, 0, 'Il joue seul, dans une cabane au fond de son jardin.', 1),
    ('dacf4d9a-8b7a-5796-ac0f-9c83ca552041'::uuid, 'e05b1966-f1f7-5768-9288-0639e54ab604'::uuid, 'Pourquoi Sainte Colombe s’est-il retiré du monde ?', 'mcq', '["Il est inconsolable de la mort de sa femme","Il a été chassé de la cour","Il est ruiné","Il est malade"]'::jsonb, 0, 'Elle lui apparaît parfois quand il joue.', 2),
    ('fd202cca-4ea7-543d-9bc1-341cfcf65a34'::uuid, 'e05b1966-f1f7-5768-9288-0639e54ab604'::uuid, 'Pourquoi refuse-t-il Marin Marais comme élève ?', 'mcq', '["Il le juge trop soucieux de plaire","Il est trop âgé","Il ne sait pas jouer","Il n’a pas d’argent"]'::jsonb, 0, 'Marais deviendra pourtant musicien du roi.', 3),
    ('b5ac6c84-1726-528a-bc05-2e5733742d01'::uuid, 'e05b1966-f1f7-5768-9288-0639e54ab604'::uuid, 'Que se passe-t-il à la fin du roman ?', 'mcq', '["Une dernière leçon nocturne, sur la mort et sur la musique","Sainte Colombe entre à la cour","Marais renonce à la musique","Ils se brouillent définitivement"]'::jsonb, 0, 'Marais revient écouter en secret le vieux maître.', 4),
    ('f077cad8-245c-5c8c-80cf-4c6d8498c683'::uuid, 'e05b1966-f1f7-5768-9288-0639e54ab604'::uuid, 'Quelle opposition structure le livre ?', 'mcq', '["La musique de cour et la musique vraie","La ville et la campagne","La foi et la raison","La jeunesse et la vieillesse seulement"]'::jsonb, 0, 'Le succès contre la recherche du silence.', 5),
    ('336dd694-9ec1-59d9-ae89-328d0829c20b'::uuid, 'e05b1966-f1f7-5768-9288-0639e54ab604'::uuid, 'Le livre est écrit dans une langue abondante et ornée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Langue sèche, rythmée, chapitres très courts, sans effets.', 6),
    ('2bd32d6d-2cc8-527b-971c-df2b282ac69d'::uuid, 'c5b91ddc-800b-5627-9990-11ba5d0a1480'::uuid, 'Quelle affaire judiciaire a déclenché le Traité ?', 'mcq', '["L’affaire Calas, à Toulouse","L’affaire du chevalier de La Barre","L’affaire Sirven","L’affaire du collier"]'::jsonb, 0, 'Jean Calas fut roué vif en 1762, sans preuve.', 1),
    ('afcb7444-06bc-5fe8-9e98-f16405cda2fe'::uuid, 'c5b91ddc-800b-5627-9990-11ba5d0a1480'::uuid, 'De quoi Jean Calas était-il accusé ?', 'mcq', '["D’avoir tué son fils pour l’empêcher de se convertir au catholicisme","De vol","D’hérésie","De complot contre le roi"]'::jsonb, 0, 'La rumeur publique a suffi à le condamner.', 2),
    ('a51c3e35-d4fe-54bf-8aef-21e7ae320752'::uuid, 'c5b91ddc-800b-5627-9990-11ba5d0a1480'::uuid, 'Quel fut le résultat de la campagne de Voltaire ?', 'mcq', '["Le jugement fut cassé en 1765 et Calas réhabilité","Rien ne changea","Voltaire fut emprisonné","La famille dut s’exiler définitivement"]'::jsonb, 0, 'Première grande victoire de l’opinion publique en France.', 3),
    ('87811ef1-6718-58fd-9fe2-98b8b9b4b3f3'::uuid, 'c5b91ddc-800b-5627-9990-11ba5d0a1480'::uuid, 'Sur quel texte le Traité s’achève-t-il ?', 'mcq', '["La Prière à Dieu","Une lettre au roi","Un poème","Un dialogue"]'::jsonb, 0, 'Elle demande que les différences ne soient pas des signaux de haine.', 4),
    ('8f4afb91-90ab-50a8-8d59-5053a6a35dc4'::uuid, 'c5b91ddc-800b-5627-9990-11ba5d0a1480'::uuid, 'Que démontre le livre au-delà du cas particulier ?', 'mcq', '["Que l’intolérance n’a de fondement ni dans la raison, ni dans le droit, ni dans l’Évangile","Que la justice royale est parfaite","Que la religion doit être supprimée","Que Toulouse est fanatique"]'::jsonb, 0, 'Le cas devient une question universelle.', 5),
    ('df90170f-3edb-55b1-b21e-acb8fe9b9121'::uuid, 'c5b91ddc-800b-5627-9990-11ba5d0a1480'::uuid, 'Voltaire réclame la suppression de toute religion.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il réclame la tolérance, pas l’athéisme d’État.', 6),
    ('5231d844-6f9f-50ec-8ba9-35eeaf203841'::uuid, 'aa44fab2-7078-5deb-9c3b-a25d4d33265b'::uuid, 'Sous quelle forme le récit nous est-il parvenu ?', 'mcq', '["En versions fragmentaires du XIIe siècle, reconstituées ensuite","En un roman unique et complet","Uniquement par la tradition orale","Par une chanson de geste"]'::jsonb, 0, 'Béroul, Thomas et Marie de France ; reconstitution de Bédier en 1900.', 1),
    ('4d0b1f3c-e693-5559-b030-8cc0c96f0687'::uuid, 'aa44fab2-7078-5deb-9c3b-a25d4d33265b'::uuid, 'Quel objet déclenche la passion ?', 'mcq', '["Un philtre bu par erreur sur le bateau","Un anneau magique","Une épée","Une lettre"]'::jsonb, 0, 'Il était destiné au roi Marc et à Iseult.', 2),
    ('922f3d55-544d-53b8-b535-69faa23ee92b'::uuid, 'aa44fab2-7078-5deb-9c3b-a25d4d33265b'::uuid, 'Quel est le rôle du philtre dans le sens du récit ?', 'mcq', '["Il rend l’amour irrésistible et donc innocent","Il punit les amants","Il révèle un amour déjà existant","Il n’a aucun effet"]'::jsonb, 0, 'C’est ce qui distingue Tristan des amants coupables.', 3),
    ('0efb7f69-b8ff-5a28-aa37-d4fe9e87f82a'::uuid, 'aa44fab2-7078-5deb-9c3b-a25d4d33265b'::uuid, 'Qui est Iseult aux Blanches Mains ?', 'mcq', '["La femme que Tristan épouse loin d’Iseult la Blonde","La sœur d’Iseult","La mère de Tristan","La reine d’Irlande"]'::jsonb, 0, 'C’est elle qui ment sur la couleur de la voile.', 4),
    ('76b71ac0-1728-5b70-8cd2-4c0c5bbc7efa'::uuid, 'aa44fab2-7078-5deb-9c3b-a25d4d33265b'::uuid, 'Comment meurent les amants ?', 'mcq', '["Tristan meurt en croyant Iseult absente, elle meurt sur son corps","Ils sont exécutés","Ils se noient","Ils meurent de vieillesse"]'::jsonb, 0, 'Une ronce pousse sur leurs tombes.', 5),
    ('c3c6f94b-5046-5d19-abbf-b2b910e44c8b'::uuid, 'aa44fab2-7078-5deb-9c3b-a25d4d33265b'::uuid, 'Le récit fonde le mythe de la passion contre la loi.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Denis de Rougemont en a fait la matrice de l’amour occidental.', 6),
    ('548b5c34-5ec5-58b2-b90f-51a0d2ec6580'::uuid, 'e0846792-30ee-512f-b54d-9fca3a78a0eb'::uuid, 'En quelle année Tropismes a-t-il paru ?', 'mcq', '["1939, dans l’indifférence générale","1957","1926","1968"]'::jsonb, 0, 'La réédition de 1957 lui donnera son statut.', 1),
    ('76968cd5-5d62-5053-ad6f-a24768b5fe07'::uuid, 'e0846792-30ee-512f-b54d-9fca3a78a0eb'::uuid, 'Que désigne le mot « tropisme » ?', 'mcq', '["Un mouvement intérieur infime, sous la conversation","Une figure de style","Un type de personnage","Une structure narrative"]'::jsonb, 0, 'Le mot est emprunté à la biologie.', 2),
    ('47ff5364-de12-5b27-8663-1564bb62b59a'::uuid, 'e0846792-30ee-512f-b54d-9fca3a78a0eb'::uuid, 'Que contient le livre ?', 'mcq', '["Vingt-quatre textes brefs sans intrigue ni personnages nommés","Un roman continu","Des poèmes","Un essai théorique"]'::jsonb, 0, '« Ils », « elle », « on » remplacent les noms.', 3),
    ('b17657b5-6d4a-593f-be50-b8c7930c86ca'::uuid, 'e0846792-30ee-512f-b54d-9fca3a78a0eb'::uuid, 'Comment Sarraute rend-elle sensible l’impalpable ?', 'mcq', '["Par des images concrètes : bêtes, liquides, insectes","Par des définitions abstraites","Par des dialogues explicites","Par des notes de bas de page"]'::jsonb, 0, 'La comparaison développée est son outil principal.', 4),
    ('e8c055a4-4273-502c-b3db-ad2742b61df4'::uuid, 'e0846792-30ee-512f-b54d-9fca3a78a0eb'::uuid, 'À quel mouvement le livre est-il rattaché ?', 'mcq', '["Le Nouveau Roman","Le surréalisme","L’existentialisme","Le naturalisme"]'::jsonb, 0, 'Après sa réédition, il devient un texte de référence.', 5),
    ('526a49f7-d6fd-5602-a238-24062592507d'::uuid, 'e0846792-30ee-512f-b54d-9fca3a78a0eb'::uuid, 'Sarraute a abandonné cette notion dans la suite de son œuvre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Toute son œuvre, romans, essais et théâtre, en découle.', 6),
    ('dedd9081-90ba-554c-ad80-de8e21937b75'::uuid, '4a775d97-6113-5bed-944e-8d3616c53b80'::uuid, 'Où et quand se déroule le roman ?', 'mcq', '["Dans les Ardennes, de l’automne 1939 à mai 1940","En Alsace, en 1914","En Normandie, en 1944","Dans les Alpes, en 1940"]'::jsonb, 0, 'C’est la période dite de la drôle de guerre.', 1),
    ('41e06a6f-6817-5cfe-99b1-3802c1e8ec6a'::uuid, '4a775d97-6113-5bed-944e-8d3616c53b80'::uuid, 'Quelle est la mission de l’aspirant Grange ?', 'mcq', '["Commander une « maison forte » perdue dans la forêt","Diriger un régiment","Assurer la liaison radio","Former des recrues"]'::jsonb, 0, 'Trois hommes seulement sont sous ses ordres.', 2),
    ('9f3201e4-e669-585d-a6ff-e0f5081187ac'::uuid, '4a775d97-6113-5bed-944e-8d3616c53b80'::uuid, 'Qui est Mona ?', 'mcq', '["Une jeune veuve du village, avec qui Grange vit une liaison","Une infirmière militaire","La sœur d’un soldat","Une réfugiée belge"]'::jsonb, 0, 'La liaison se déroule dans un temps suspendu.', 3),
    ('12ce3440-02fd-5e73-a057-58fde54503c7'::uuid, '4a775d97-6113-5bed-944e-8d3616c53b80'::uuid, 'Que se passe-t-il en mai 1940 ?', 'mcq', '["L’offensive allemande balaie tout en quelques heures","La guerre s’arrête","Grange est muté","La maison forte résiste"]'::jsonb, 0, 'La longue attente s’achève en désastre immédiat.', 4),
    ('9f890f74-51d2-5db9-bb0d-078c4797bafe'::uuid, '4a775d97-6113-5bed-944e-8d3616c53b80'::uuid, 'Quel élément fonctionne comme un personnage du roman ?', 'mcq', '["La forêt","Le blockhaus seul","Le fleuve","Le village"]'::jsonb, 0, 'Gracq était géographe de formation.', 5),
    ('6047fb4d-dee0-5d76-ad7b-9f33c1904d85'::uuid, '4a775d97-6113-5bed-944e-8d3616c53b80'::uuid, 'Gracq a accepté le prix Goncourt en 1951.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il l’a refusé, après avoir publié un pamphlet contre le milieu littéraire.', 6),
    ('efcf6cc8-45f9-52b6-b14e-e7b94bbe04da'::uuid, '35cd4862-9db6-522c-a386-68737f46de45'::uuid, 'Qu’a acheté la mère à l’administration coloniale ?', 'mcq', '["Une concession régulièrement envahie par la mer","Une plantation d’hévéas prospère","Une maison à Saigon","Un bateau"]'::jsonb, 0, 'L’administration corrompue lui a vendu une terre incultivable.', 1),
    ('e7eac020-7a76-546c-bd9c-f04d85216b4c'::uuid, '35cd4862-9db6-522c-a386-68737f46de45'::uuid, 'Que construit-elle avec les paysans ?', 'mcq', '["Des barrages de rondins contre le Pacifique","Une école","Une digue en béton","Un canal d’irrigation"]'::jsonb, 0, 'La mer les emporte.', 2),
    ('f2832717-24d8-5327-ae65-942ca6797b35'::uuid, '35cd4862-9db6-522c-a386-68737f46de45'::uuid, 'Qui est Monsieur Jo ?', 'mcq', '["Un riche héritier laid et timide qui convoite Suzanne","Un fonctionnaire colonial","Le frère aîné","Un planteur français ami de la famille"]'::jsonb, 0, 'La mère espère un mariage et obtient un diamant.', 3),
    ('6bc5479b-934d-5245-81e7-2493633e27ba'::uuid, '35cd4862-9db6-522c-a386-68737f46de45'::uuid, 'Quel lien ce roman entretient-il avec L’Amant ?', 'mcq', '["Il raconte la même enfance sous une autre forme","Il en est la suite","Il n’a aucun rapport","Il en est une réécriture par un autre auteur"]'::jsonb, 0, 'Duras reviendra sur cette matière en 1984.', 4),
    ('194b6e5f-7cb0-5513-8b8a-70c5af25cec1'::uuid, '35cd4862-9db6-522c-a386-68737f46de45'::uuid, 'Que dénonce le roman ?', 'mcq', '["La corruption coloniale et la misère des paysans indochinois","La guerre d’Indochine","La politique française en Algérie","L’exode rural en France"]'::jsonb, 0, 'Il a failli obtenir le Goncourt en 1950.', 5),
    ('8ddcd095-67c2-5696-bc3a-92c3a6b2fe4e'::uuid, '35cd4862-9db6-522c-a386-68737f46de45'::uuid, 'L’écriture est déjà celle, très fragmentée, de L’Amant.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est encore classique, mais tendue par la répétition.', 6),
    ('45c459af-32c5-5a01-bfb6-8c9a2b33f7f3'::uuid, '4bc7b166-5257-548a-bb31-fbb9a34eb49f'::uuid, 'Quelle particularité éditoriale ce livre présente-t-il ?', 'mcq', '["C’est le seul que Rimbaud ait publié lui-même","Il a été publié par Verlaine","Il est posthume","Il a paru en revue seulement"]'::jsonb, 0, 'À compte d’auteur, à Bruxelles, en 1873.', 1),
    ('121cb58b-2b57-5e68-9142-79cb520a1fff'::uuid, '4bc7b166-5257-548a-bb31-fbb9a34eb49f'::uuid, 'Quel épisode biographique précède l’écriture ?', 'mcq', '["La rupture violente avec Verlaine à Bruxelles","Son départ pour l’Abyssinie","La Commune de Paris","Son entrée au lycée"]'::jsonb, 0, 'Verlaine avait tiré sur lui.', 2),
    ('0466965e-ac62-5af6-8ee9-0d8a31eb75a3'::uuid, '4bc7b166-5257-548a-bb31-fbb9a34eb49f'::uuid, 'Que fait Rimbaud dans « Alchimie du verbe » ?', 'mcq', '["Il raconte et juge sa propre entreprise poétique","Il décrit un voyage","Il attaque ses contemporains","Il traduit un texte latin"]'::jsonb, 0, 'C’est un bilan critique de son projet de voyant.', 3),
    ('1067975c-ca9e-5c96-a021-3165f6c4e3c3'::uuid, '4bc7b166-5257-548a-bb31-fbb9a34eb49f'::uuid, 'Quelle formule célèbre le livre contient-il ?', 'mcq', '["« Il faut être absolument moderne »","« Je est un autre »","« La beauté sera convulsive »","« Changer la vie »"]'::jsonb, 0, 'Elle figure dans la section « Adieu ».', 4),
    ('883be4cd-4eb1-5944-9700-ab747ed0aaec'::uuid, '4bc7b166-5257-548a-bb31-fbb9a34eb49f'::uuid, 'Que fait Rimbaud après ce livre ?', 'mcq', '["Il cesse peu à peu d’écrire et part à l’étranger","Il publie dix recueils","Il devient critique","Il enseigne à Paris"]'::jsonb, 0, 'Chypre, l’Abyssinie, le commerce ; il meurt à trente-sept ans.', 5),
    ('175d7cac-dcc7-5816-b157-8f77957eb3c1'::uuid, '4bc7b166-5257-548a-bb31-fbb9a34eb49f'::uuid, '« Délires I » raconte la vie commune avec Verlaine du point de vue de Rimbaud.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est la « Vierge folle » — l’autre — qui parle de « l’Époux infernal ».', 6),
    ('d541c30a-245d-5295-854c-126702f38e19'::uuid, 'b4ec9000-7740-52e0-b7c4-b7b6f698ac8f'::uuid, 'Comment Maupassant sous-titre-t-il son roman ?', 'mcq', '["« L’humble vérité »","« Mœurs de province »","« Chronique de 1880 »","« Scènes normandes »"]'::jsonb, 0, 'Le programme réaliste est annoncé dès le titre.', 1),
    ('0020b7d0-947f-51d7-95ff-dfe2d276fbfd'::uuid, 'b4ec9000-7740-52e0-b7c4-b7b6f698ac8f'::uuid, 'Qui est Julien de Lamare ?', 'mcq', '["Le mari séduisant et avare de Jeanne","Son père","Son fils","Le curé du village"]'::jsonb, 0, 'Il la déçoit dès le voyage de noces.', 2),
    ('1a303bc7-b4d1-5302-af97-c3d6eb668419'::uuid, 'b4ec9000-7740-52e0-b7c4-b7b6f698ac8f'::uuid, 'Comment meurt Julien ?', 'mcq', '["Le mari trompé pousse la cabane des amants dans un ravin","D’une maladie","En duel","Noyé"]'::jsonb, 0, 'La scène est l’un des rares événements violents du roman.', 3),
    ('ff2ba89e-be39-5cf0-b877-77aa6330c24f'::uuid, 'b4ec9000-7740-52e0-b7c4-b7b6f698ac8f'::uuid, 'Que fait le fils Paul ?', 'mcq', '["Il ruine méthodiquement sa mère depuis Paris","Il devient officier","Il soigne sa mère","Il meurt jeune"]'::jsonb, 0, 'Jeanne lui avait reporté tout son amour.', 4),
    ('45ab35c9-de08-5edf-9c10-0a765e404847'::uuid, 'b4ec9000-7740-52e0-b7c4-b7b6f698ac8f'::uuid, 'Quelle est la phrase qui clôt le roman ?', 'mcq', '["« La vie, voyez-vous, ça n’est jamais si bon ni si mauvais qu’on croit »","« Tout est perdu »","« Il faut recommencer »","« Ainsi va le monde »"]'::jsonb, 0, 'Elle est prononcée par Rosalie.', 5),
    ('7502e10a-86bc-5f2d-ab4e-994e794ad0e7'::uuid, 'b4ec9000-7740-52e0-b7c4-b7b6f698ac8f'::uuid, 'Jeanne finit par se révolter contre son sort.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est ce qui la distingue d’Emma Bovary : elle subit sans jamais se révolter.', 6),
    ('53d33575-3258-5b56-967f-686fc8e686d3'::uuid, 'c01a1bbe-0358-5d70-ad08-20927df576b5'::uuid, 'De quel roman ce livre est-il la réécriture ?', 'mcq', '["Robinson Crusoé de Defoe","L’Île mystérieuse de Verne","Sa Majesté des Mouches","Le Voyage de Gulliver"]'::jsonb, 0, 'Tournier en inverse le sens.', 1),
    ('cb7d7a28-9b00-5ce6-af37-0ec0963158aa'::uuid, 'c01a1bbe-0358-5d70-ad08-20927df576b5'::uuid, 'Que fait Robinson au début de son séjour ?', 'mcq', '["Il reconstitue la civilisation : cadastre, code, calendrier","Il tente de construire un radeau","Il vit nu et sans règles","Il cherche Vendredi"]'::jsonb, 0, 'Une colonie administrée pour lui seul.', 2),
    ('a62cc2de-86ac-597f-b4f1-5f204d7af7ac'::uuid, 'c01a1bbe-0358-5d70-ad08-20927df576b5'::uuid, 'Qu’est-ce qui détruit cet ordre ?', 'mcq', '["Une explosion provoquée par Vendredi dans la grotte aux poudres","Un cyclone","Un tremblement de terre","Un incendie de forêt"]'::jsonb, 0, 'Elle libère Robinson de son propre système.', 3),
    ('4e589be4-6e54-5066-927a-9433eb59be3f'::uuid, 'c01a1bbe-0358-5d70-ad08-20927df576b5'::uuid, 'Quel est le renversement central du roman ?', 'mcq', '["Le « sauvage » libère le civilisé","Le civilisé convertit le sauvage","Les deux hommes s’entretuent","Robinson rentre en Angleterre"]'::jsonb, 0, 'C’est l’inverse exact du roman de Defoe.', 4),
    ('b733aef4-3bb2-50ea-bb7f-6d6620bf3ea7'::uuid, 'c01a1bbe-0358-5d70-ad08-20927df576b5'::uuid, 'Que fait Robinson quand un navire aborde ?', 'mcq', '["Il refuse de partir ; c’est Vendredi qui s’embarque","Il part aussitôt","Il cache Vendredi","Il attaque l’équipage"]'::jsonb, 0, 'Un jeune mousse reste avec lui : il le nomme Jeudi.', 5),
    ('5d776a46-a83e-562e-9af1-d245a4394481'::uuid, 'c01a1bbe-0358-5d70-ad08-20927df576b5'::uuid, 'Il existe une version pour la jeunesse de ce roman.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Vendredi ou la Vie sauvage, publiée en 1971, encore plus lue que l’original.', 6),
    ('07ba63cf-1cb0-5634-bc8a-05262dfbb0cb'::uuid, 'ad5d89f4-e2dd-54f7-ab31-6a7abb97bdc1'::uuid, 'Où se déroule le roman ?', 'mcq', '["En Amérique du Sud, aux débuts de l’Aéropostale","En Afrique du Nord","En France","Aux États-Unis"]'::jsonb, 0, 'Trois courriers de nuit convergent vers Buenos Aires.', 1),
    ('79bfe415-fb8f-5a50-a3c6-cbcc9a6f7259'::uuid, 'ad5d89f4-e2dd-54f7-ab31-6a7abb97bdc1'::uuid, 'Qui est Rivière ?', 'mcq', '["Le directeur d’exploitation, exigeant et inflexible","Un pilote","Un mécanicien","Le mari de la femme qui attend"]'::jsonb, 0, 'Sa dureté a pour but la régularité de la ligne.', 2),
    ('47f5fd14-2940-5faf-a346-224dfda89bf1'::uuid, 'ad5d89f4-e2dd-54f7-ab31-6a7abb97bdc1'::uuid, 'Qu’arrive-t-il à Fabien ?', 'mcq', '["Il est pris dans un cyclone et disparaît","Il atterrit en catastrophe","Il abandonne son poste","Il est sauvé au dernier moment"]'::jsonb, 0, 'Il monte au-dessus des nuages jusqu’à la panne sèche.', 3),
    ('4c9373cd-45ac-548a-a3cf-c2f09435d08e'::uuid, 'ad5d89f4-e2dd-54f7-ab31-6a7abb97bdc1'::uuid, 'Que fait Rivière à l’aube ?', 'mcq', '["Il fait partir le courrier d’Europe","Il démissionne","Il organise les recherches","Il annonce la nouvelle à la presse"]'::jsonb, 0, 'La ligne continue : c’est la réponse du roman.', 4),
    ('6d8286e5-3c59-5c4a-8261-719a8360a8bc'::uuid, 'ad5d89f4-e2dd-54f7-ab31-6a7abb97bdc1'::uuid, 'Quel prix le roman a-t-il obtenu ?', 'mcq', '["Le prix Femina 1931","Le Goncourt","Le Renaudot","Le grand prix de l’Académie"]'::jsonb, 0, 'Avec une préface d’André Gide.', 5),
    ('055b58d7-fd17-581f-ba7b-3e8cd7af9c96'::uuid, 'ad5d89f4-e2dd-54f7-ab31-6a7abb97bdc1'::uuid, 'Saint-Exupéry écrivait sans connaître le métier de pilote.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il était pilote de ligne : le livre naît de son expérience.', 6),
    ('207dd348-bd88-53a8-a1a5-9144cb997510'::uuid, 'ae6261e6-b153-5922-8c5d-fe9a840e2ef7'::uuid, 'Quelles étapes le voyage de Bardamu comporte-t-il ?', 'mcq', '["La guerre, l’Afrique coloniale, les États-Unis, la banlieue parisienne","L’Espagne, l’Italie, la Grèce","La Russie et la Chine","Uniquement Paris"]'::jsonb, 0, 'Chaque étape révèle un visage du même mensonge.', 1),
    ('71669edf-ca0c-5ba4-8d99-41e8bd1c0f34'::uuid, 'ae6261e6-b153-5922-8c5d-fe9a840e2ef7'::uuid, 'Quelle révolution le roman apporte-t-il ?', 'mcq', '["La langue parlée entre dans la narration elle-même","Le retour au récit classique","La suppression des dialogues","L’usage du présent de narration"]'::jsonb, 0, 'Argot, ellipses, rythme haché, points de suspension.', 2),
    ('2576105a-593e-5df2-89b7-e3c3f8a6ed18'::uuid, 'ae6261e6-b153-5922-8c5d-fe9a840e2ef7'::uuid, 'Qui est Robinson ?', 'mcq', '["Le double sombre qui suit Bardamu partout","Son frère","Son médecin","Un officier"]'::jsonb, 0, 'Il finit assassiné par sa fiancée Madelon.', 3),
    ('da1970fb-964c-515c-8ead-771671a5da28'::uuid, 'ae6261e6-b153-5922-8c5d-fe9a840e2ef7'::uuid, 'Quel prix le roman a-t-il obtenu ?', 'mcq', '["Le prix Renaudot 1932","Le Goncourt","Le Femina","Aucun"]'::jsonb, 0, 'Il rate le Goncourt de peu.', 4),
    ('7db0c802-cd95-5fee-8267-cec10c103c66'::uuid, 'ae6261e6-b153-5922-8c5d-fe9a840e2ef7'::uuid, 'Que faut-il savoir de l’auteur ?', 'mcq', '["Il a publié à partir de 1937 des pamphlets antisémites d’une extrême violence","Il a été résistant","Il a cessé d’écrire après 1932","Il a émigré aux États-Unis"]'::jsonb, 0, 'Sa condamnation est aujourd’hui unanime, et son cas indissociable de cette question.', 5),
    ('cd10091e-b5f2-53b3-b91b-0d414bec7d34'::uuid, 'ae6261e6-b153-5922-8c5d-fe9a840e2ef7'::uuid, 'La langue parlée n’apparaît que dans les dialogues du roman.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle envahit la narration : c’est précisément ce qui fait la rupture.', 6),
    ('b88196b6-3ff9-5519-a3de-d0fa8f46438c'::uuid, '620a46e3-8eaa-51e9-899b-47b0697d213c'::uuid, 'Comment le voyage est-il décidé ?', 'mcq', '["Un cryptogramme trouvé dans un vieux livre islandais","Une carte achetée à Hambourg","Un rêve du professeur","Une lettre anonyme"]'::jsonb, 0, 'Il est signé de l’alchimiste Arne Saknussemm.', 1),
    ('c782f5dd-8cb8-59d3-a936-0eeed35be0c7'::uuid, '620a46e3-8eaa-51e9-899b-47b0697d213c'::uuid, 'Par où les explorateurs descendent-ils ?', 'mcq', '["Le cratère du Sneffels, en Islande","Une mine allemande","Le Vésuve","Une grotte des Alpes"]'::jsonb, 0, 'Ils ressortiront par le Stromboli.', 2),
    ('fe76d9f1-d9c0-5971-8eba-517d4372a9a8'::uuid, '620a46e3-8eaa-51e9-899b-47b0697d213c'::uuid, 'Qui est Hans ?', 'mcq', '["Le guide islandais, impassible et efficace","Le neveu du professeur","Un savant rival","Un marin norvégien"]'::jsonb, 0, 'Le trio associe le savant, le peureux et le guide.', 3),
    ('921cc4ff-8b4b-5958-9ab0-5a706428e72f'::uuid, '620a46e3-8eaa-51e9-899b-47b0697d213c'::uuid, 'Que découvrent-ils au plus profond ?', 'mcq', '["Un océan souterrain avec des monstres préhistoriques","Une cité perdue","Un gisement d’or","Rien : ils rebroussent chemin"]'::jsonb, 0, 'Verne y met en scène la paléontologie de son temps.', 4),
    ('cef030dc-22bd-52ee-9969-0fd78113e830'::uuid, '620a46e3-8eaa-51e9-899b-47b0697d213c'::uuid, 'Comment remontent-ils à la surface ?', 'mcq', '["Portés par une éruption volcanique","Par le même chemin","Par un puits de mine","Par un tunnel marin"]'::jsonb, 0, 'Ils émergent au Stromboli, en Italie.', 5),
    ('21b12cfe-c127-56a0-95b7-07a4913f690b'::uuid, '620a46e3-8eaa-51e9-899b-47b0697d213c'::uuid, 'Le roman ne contient aucun contenu scientifique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Géologie, minéralogie et paléontologie y tiennent une grande place : instruire en amusant.', 6),
    ('aaafc8da-0382-51ab-b46d-a13ee333e85d'::uuid, 'b3203244-1062-5cc3-9f56-41f8d167382d'::uuid, 'Que vaut à Zadig sa fameuse description du chien et du cheval ?', 'mcq', '["Une accusation de vol","Une récompense royale","Un poste de juge","L’exil immédiat"]'::jsonb, 0, 'La page est souvent citée comme un ancêtre du raisonnement policier.', 1),
    ('66664d8d-42d7-534d-ae65-43e45290a31c'::uuid, 'b3203244-1062-5cc3-9f56-41f8d167382d'::uuid, 'Qui est Jesrad ?', 'mcq', '["Un ermite qui se révèle être un ange","Le roi de Babylone","Un juge corrompu","Le rival de Zadig"]'::jsonb, 0, 'Il explique que chaque mal engendre un bien.', 2),
    ('f07c38a0-5842-56a4-9d74-ea6dd977ed25'::uuid, 'b3203244-1062-5cc3-9f56-41f8d167382d'::uuid, 'Quelle question philosophique le conte pose-t-il ?', 'mcq', '["Celle de la providence et de l’existence du mal","Celle de la liberté politique","Celle de la propriété","Celle de l’éducation"]'::jsonb, 0, 'Voltaire y est encore proche de l’optimisme leibnizien.', 3),
    ('e6131496-8503-57d3-8c82-827006df5f3d'::uuid, 'b3203244-1062-5cc3-9f56-41f8d167382d'::uuid, 'Quel conte viendra contredire cette position ?', 'mcq', '["Candide, en 1759","L’Ingénu","Micromégas","Le Taureau blanc"]'::jsonb, 0, 'Après le tremblement de terre de Lisbonne.', 4),
    ('4dbc201a-65c2-5528-85ad-0005d79bc352'::uuid, 'b3203244-1062-5cc3-9f56-41f8d167382d'::uuid, 'Que vise la satire de Zadig ?', 'mcq', '["La justice, les courtisans et les querelles religieuses","Le commerce","L’armée","La médecine"]'::jsonb, 0, 'Babylone est un décor transparent pour la France.', 5),
    ('03eaa0cf-7775-522c-8072-64dd18e46043'::uuid, 'b3203244-1062-5cc3-9f56-41f8d167382d'::uuid, 'Zadig finit ruiné et exilé.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il retrouve le trône et la reine Astarté à la fin du conte.', 6),
    ('86c2385a-82fa-55fb-a8be-fede79d8943e'::uuid, '02cdad23-ef9e-5d36-bbca-80d560ce259e'::uuid, 'Que veut absolument faire Zazie à Paris ?', 'mcq', '["Prendre le métro","Voir la tour Eiffel","Rencontrer son père","Aller au cinéma"]'::jsonb, 0, 'Le métro est justement en grève.', 1),
    ('7df854d6-a053-5b22-9839-cf9ec9cbae15'::uuid, '02cdad23-ef9e-5d36-bbca-80d560ce259e'::uuid, 'Quel est le premier mot du roman ?', 'mcq', '["« Doukipudonktan »","« Zazie »","« Paris »","« Alors »"]'::jsonb, 0, 'Transcription phonétique de « D’où qu’ils puent donc tant ? ».', 2),
    ('ec910275-8fc2-50d0-9ffd-1fa27959cf6c'::uuid, '02cdad23-ef9e-5d36-bbca-80d560ce259e'::uuid, 'Quel est le métier de l’oncle Gabriel ?', 'mcq', '["Danseur de charme dans un cabaret","Chauffeur de taxi","Professeur","Cuisinier"]'::jsonb, 0, 'Il héberge Zazie pendant deux jours.', 3),
    ('f3e22fbf-4056-51ad-ba8f-e4cc768a6c08'::uuid, '02cdad23-ef9e-5d36-bbca-80d560ce259e'::uuid, 'Que répète le perroquet Laverdure ?', 'mcq', '["« Tu causes, tu causes, c’est tout ce que tu sais faire »","« Doukipudonktan »","« Zazie, Zazie »","« Le métro, le métro »"]'::jsonb, 0, 'Le leitmotiv ponctue tout le roman.', 4),
    ('72738335-9120-5771-bbdd-1dce9741a2ee'::uuid, '02cdad23-ef9e-5d36-bbca-80d560ce259e'::uuid, 'Que répond Zazie à la fin, sur ce qu’elle a fait ?', 'mcq', '["« J’ai vieilli »","« J’ai pris le métro »","« Rien du tout »","« Je me suis amusée »"]'::jsonb, 0, 'La chute est célèbre.', 5),
    ('5dc43fee-2925-584d-b610-6577c5756649'::uuid, '02cdad23-ef9e-5d36-bbca-80d560ce259e'::uuid, 'Queneau était membre fondateur de l’Oulipo.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’Ouvroir de littérature potentielle, fondé en 1960 avec François Le Lionnais.', 6)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('francais');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('francais')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 265 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 265 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
